/* ------------------------------------------------------------------------ */
/* Model                                                                     */
/* ------------------------------------------------------------------------ */

type Priority = 0 | 1 | 2 | 3 | 4;

interface Person {
  id: string;
  name: string;
  initials: string;
  role: string;
  /** A solid fill that carries a white label. */
  color: string;
  avatarUrl?: string;
}

interface Label {
  id: string;
  name: string;
  color: string;
}

interface Column {
  id: string;
  name: string;
  color: string;
  /** Work-in-progress limit. The count turns amber past it. */
  limit?: number;
}

interface Activity {
  id: string;
  text: string;
  at: string;
}

interface Card {
  id: string;
  key: string;
  title: string;
  description: string;
  columnId: string;
  labelIds: string[];
  assigneeId: string | null;
  priority: Priority;
  /** ISO dates, yyyy-mm-dd. */
  start: string | null;
  due: string | null;
  /** Story points. */
  estimate: number | null;
  /** A sub-issue points at its parent; the parent's progress counts its children. */
  parentId: string | null;
  createdAt: string;
  /** Set when the card reaches Done, cleared if it leaves. Drives the burn-up. */
  closedAt: string | null;
  /** GitHub's own sub-issue count, for an imported parent whose children stayed on GitHub. */
  remoteProgress?: { done: number; total: number };
  activity: Activity[];
  /** Set on cards pulled from GitHub: the issue page, and a key for skipping repeats. */
  source?: { url: string; ref: string };
}

interface Board {
  columns: Column[];
  labels: Label[];
  /** The seed team, plus anyone an imported issue was assigned to. */
  people: Person[];
  /** Order in this array is the order inside each column. */
  cards: Card[];
  seq: number;
}

const PRIORITIES = ["No priority", "Low", "Medium", "High", "Urgent"] as const;

/** Where the "done" chime and the sprint progress read from. */
const DONE_ID = "done";

/**
 * A fixed "today" keeps the demo deterministic: every due-date chip renders
 * the same on the server and in the browser. In a real app this is the
 * current date.
 */
const TODAY = "2026-09-29";
const SPRINT_START = "2026-09-22";
const SPRINT_END = "2026-10-05";
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function dayNumber(iso: string) {
  const [y, m, d] = iso.split("-").map(Number);
  return Math.round(Date.UTC(y, m - 1, d) / 86_400_000);
}

function shortDate(iso: string) {
  const [, m, d] = iso.split("-").map(Number);
  return `${MONTHS[m - 1]} ${d}`;
}

function dueState(iso: string | null, columnId: string): "none" | "overdue" | "soon" | "later" {
  if (!iso || columnId === DONE_ID) return "none";
  const diff = dayNumber(iso) - dayNumber(TODAY);
  if (diff < 0) return "overdue";
  if (diff <= 2) return "soon";
  return "later";
}

