/** Keys run on from the seed: HBR-128 to HBR-147, so the first new card is HBR-148. */
const FIRST_NEW_KEY = 128 + SEED_CARDS.length;

function seedBoard(): Board {
  const cards: Card[] = SEED_CARDS.map((s, i) => ({
    id: `c${i + 1}`,
    key: `HBR-${128 + i}`,
    title: s.title,
    description: s.description ?? "",
    columnId: s.column,
    labelIds: s.labels,
    assigneeId: s.who,
    priority: s.priority,
    estimate: s.estimate,
    start: s.start ?? null,
    due: s.due ?? null,
    parentId: s.parent ? `c${s.parent}` : null,
    createdAt: s.created ?? SPRINT_START,
    closedAt: s.closed ?? null,
    activity: [
      {
        id: `c${i + 1}a0`,
        text: `Created in ${SEED_COLUMNS.find((c) => c.id === s.column)?.name}`,
        at: shortDate(s.created ?? SPRINT_START),
      },
    ],
  }));
  return { columns: SEED_COLUMNS, labels: SEED_LABELS, people: PEOPLE, cards, seq: 1000 };
}

/* ------------------------------------------------------------------------ */
/* Board operations                                                          */
/* ------------------------------------------------------------------------ */

/** Moves a card to `columnId`, before `beforeId`, or to the end of the column. */
function moveCard(cards: Card[], id: string, columnId: string, beforeId: string | null): Card[] {
  const card = cards.find((c) => c.id === id);
  if (!card) return cards;
  const rest = cards.filter((c) => c.id !== id);
  const moved = { ...card, columnId };
  let at = beforeId ? rest.findIndex((c) => c.id === beforeId) : -1;
  if (at < 0) {
    const last = rest.map((c) => c.columnId).lastIndexOf(columnId);
    at = last < 0 ? rest.length : last + 1;
  }
  rest.splice(at, 0, moved);
  return rest;
}

/** Moves a card, applying `patch`, to before `beforeId`, or after the last card `inCell` accepts. */
function placeCard(
  cards: Card[],
  id: string,
  patch: Partial<Card>,
  beforeId: string | null,
  inCell: (c: Card) => boolean
): Card[] {
  const card = cards.find((c) => c.id === id);
  if (!card) return cards;
  const rest = cards.filter((c) => c.id !== id);
  let at = beforeId ? rest.findIndex((c) => c.id === beforeId) : -1;
  if (at < 0) {
    let last = -1;
    rest.forEach((c, i) => {
      if (inCell(c)) last = i;
    });
    at = last < 0 ? rest.length : last + 1;
  }
  rest.splice(at, 0, { ...card, ...patch });
  return rest;
}

/* ------------------------------------------------------------------------ */
/* Sub-issues                                                                */
/* ------------------------------------------------------------------------ */

interface Progress {
  done: number;
  total: number;
}

function childrenOf(cards: Card[]) {
  const m = new Map<string, Card[]>();
  for (const c of cards) if (c.parentId) m.set(c.parentId, [...(m.get(c.parentId) ?? []), c]);
  return m;
}

/**
 * How much of a card is covered: its sub-issues that reached Done. An
 * imported parent whose children stayed on GitHub carries GitHub's own count.
 */
function progressOf(card: Card, kids: Map<string, Card[]>): Progress | null {
  const children = kids.get(card.id) ?? [];
  if (!children.length) return card.remoteProgress ?? null;
  return { done: children.filter((c) => c.columnId === DONE_ID).length, total: children.length };
}

/** A card and everything beneath it, so a parent picker cannot make a loop. */
function familyOf(id: string, kids: Map<string, Card[]>): Set<string> {
  const out = new Set([id]);
  const stack = [id];
  while (stack.length) {
    for (const c of kids.get(stack.pop()!) ?? []) {
      if (!out.has(c.id)) {
        out.add(c.id);
        stack.push(c.id);
      }
    }
  }
  return out;
}

/** Cards above `card`, walking up its parents. */
function ancestorsOf(card: Card, cards: Card[]): Set<string> {
  const out = new Set<string>();
  let p = card.parentId;
  while (p && !out.has(p)) {
    out.add(p);
    p = cards.find((c) => c.id === p)?.parentId ?? null;
  }
  return out;
}

interface BoardCtx {
  board: Board;
  people: Map<string, Person>;
  labels: Map<string, Label>;
  kids: Map<string, Card[]>;
}

/** What a person is called in a query: their id, without an import prefix. */
const handleOf = (p: Person) => p.id.replace(/^gh:/, "").toLowerCase();

/* ------------------------------------------------------------------------ */
/* Filter query                                                              */
/*                                                                           */
/* GitHub's grammar: `field:value` qualifiers, commas for "any of",          */
/* a leading `-` to exclude, quotes around values with spaces, and bare      */
/* words matched against the title, the key and the assignee's name.         */
/* Different qualifiers AND together; values inside one qualifier OR.        */
/* ------------------------------------------------------------------------ */

type QField = "is" | "assignee" | "label" | "status" | "priority" | "due" | "parent" | "title" | "repo";

interface QToken {
  start: number;
  end: number;
  /** Index just past the colon, for qualifiers. */
  keyEnd: number;
  neg: boolean;
  field: QField | null;
  values: string[];
}

const Q_FIELDS: { key: QField; label: string; icon: LucideIcon; hint: string }[] = [
  { key: "is", label: "Is", icon: LayoutGrid, hint: "open, done, overdue" },
  { key: "assignee", label: "Assignee", icon: UserRound, hint: "a person, or none" },
  { key: "label", label: "Label", icon: Tag, hint: "any label" },
  { key: "status", label: "Status", icon: CircleDashed, hint: "a column" },
  { key: "priority", label: "Priority", icon: SignalHigh, hint: "urgent to none" },
  { key: "due", label: "Due date", icon: CalendarDays, hint: "overdue, this-week" },
  { key: "parent", label: "Parent issue", icon: CornerDownRight, hint: "a parent's key" },
  { key: "title", label: "Title", icon: CaseSensitive, hint: "words in the title" },
  { key: "repo", label: "Repository", icon: BookMarked, hint: "an imported repo" },
];
const Q_KEYS = new Set<string>(Q_FIELDS.map((f) => f.key));
const PRIORITY_KEYS = ["none", "low", "medium", "high", "urgent"] as const;

function splitValues(s: string) {
  const out: string[] = [];
  let cur = "";
  let inQ = false;
  for (const ch of s) {
    if (ch === '"') {
      inQ = !inQ;
      continue;
    }
    if (ch === "," && !inQ) {
      out.push(cur);
      cur = "";
      continue;
    }
    cur += ch;
  }
  out.push(cur);
  return out.map((v) => v.trim()).filter(Boolean);
}

const quoteValue = (v: string) => (/[\s,"]/.test(v) ? `"${v.replace(/"/g, "")}"` : v);

function tokenize(q: string): QToken[] {
  const out: QToken[] = [];
  let i = 0;
  while (i < q.length) {
    if (/\s/.test(q[i])) {
      i++;
      continue;
    }
    const start = i;
    let inQ = false;
    while (i < q.length && (inQ || !/\s/.test(q[i]))) {
      if (q[i] === '"') inQ = !inQ;
      i++;
    }
    const raw = q.slice(start, i);
    const m = raw.match(/^(-?)([a-zA-Z]+):(.*)$/);
    if (m && Q_KEYS.has(m[2].toLowerCase())) {
      const keyEnd = start + m[1].length + m[2].length + 1;
      out.push({ start, end: i, keyEnd, neg: m[1] === "-", field: m[2].toLowerCase() as QField, values: splitValues(m[3]) });
    } else {
      out.push({ start, end: i, keyEnd: start, neg: false, field: null, values: [raw.replace(/"/g, "")] });
    }
  }
  return out;
}

function fieldMatch(field: QField, v: string, c: Card, ctx: BoardCtx): boolean {
  switch (field) {
    case "is":
      if (v === "open") return c.columnId !== DONE_ID;
      if (v === "done" || v === "closed") return c.columnId === DONE_ID;
      if (v === "overdue") return dueState(c.due, c.columnId) === "overdue";
      if (v === "due-soon") return dueState(c.due, c.columnId) === "soon";
      if (v === "assigned") return !!c.assigneeId;
      if (v === "unassigned") return !c.assigneeId;
      if (v === "parent") return (ctx.kids.get(c.id)?.length ?? 0) > 0;
      if (v === "sub-issue") return !!c.parentId;
      if (v === "imported") return !!c.source;
      return false;
    case "assignee": {
      if (v === "none") return !c.assigneeId;
      const p = c.assigneeId ? ctx.people.get(c.assigneeId) : undefined;
      return !!p && (handleOf(p) === v || p.name.toLowerCase() === v);
    }
    case "label":
      return c.labelIds.some((id) => ctx.labels.get(id)?.name.toLowerCase() === v);
    case "status":
      return ctx.board.columns.find((col) => col.id === c.columnId)?.name.toLowerCase() === v;
    case "priority":
      return PRIORITY_KEYS[c.priority] === v;
    case "due": {
      if (v === "none") return !c.due;
      if (!c.due) return false;
      const diff = dayNumber(c.due) - dayNumber(TODAY);
      if (v === "overdue") return diff < 0 && c.columnId !== DONE_ID;
      if (v === "today") return diff === 0;
      if (v === "this-week") return diff >= 0 && diff <= 7;
      if (v === "next-week") return diff > 7 && diff <= 14;
      return c.due === v;
    }
    case "parent": {
      if (v === "none") return !c.parentId;
      const p = c.parentId ? ctx.board.cards.find((x) => x.id === c.parentId) : undefined;
      return !!p && p.key.toLowerCase() === v;
    }
    case "title":
      return c.title.toLowerCase().includes(v);
    case "repo":
      return !!c.source && c.source.ref.toLowerCase().startsWith(v + "#");
  }
}

function cardMatches(c: Card, tokens: QToken[], ctx: BoardCtx): boolean {
  for (const t of tokens) {
    if (t.field === null) {
      const v = t.values[0]?.toLowerCase();
      if (!v) continue;
      const who = c.assigneeId ? ctx.people.get(c.assigneeId)?.name.toLowerCase() ?? "" : "";
      if (!(c.title.toLowerCase().includes(v) || c.key.toLowerCase().includes(v) || who.includes(v))) return false;
      continue;
    }
    // A qualifier still being typed ("label:") filters nothing yet.
    if (!t.values.length) continue;
    const any = t.values.some((raw) => fieldMatch(t.field!, raw.toLowerCase(), c, ctx));
    if (any === t.neg) return false;
  }
  return true;
}

/** What the caret is sitting in: a field name being typed, or a field's value. */
type QContext =
  | { kind: "field"; from: number; to: number; prefix: string; neg: boolean }
  | { kind: "value"; field: QField; from: number; to: number; prefix: string };

function contextAt(q: string, caret: number): QContext | null {
  const tok = tokenize(q).find((t) => t.start <= caret && caret <= t.end);
  if (!tok) return { kind: "field", from: caret, to: caret, prefix: "", neg: false };
  const part = q.slice(tok.start, caret);
  const m = part.match(/^(-?)([a-zA-Z]+):(.*)$/);
  if (m) {
    if (!Q_KEYS.has(m[2].toLowerCase())) return null;
    const after = m[3];
    const lastComma = after.lastIndexOf(",");
    const from = tok.start + m[1].length + m[2].length + 1 + (lastComma + 1);
    const rest = q.slice(caret, tok.end);
    const nextComma = rest.indexOf(",");
    return {
      kind: "value",
      field: m[2].toLowerCase() as QField,
      from,
      to: nextComma < 0 ? tok.end : caret + nextComma,
      prefix: after.slice(lastComma + 1).replace(/"/g, ""),
    };
  }
  if (part.includes(":")) return null;
  return { kind: "field", from: tok.start, to: tok.end, prefix: part.replace(/^-/, ""), neg: part.startsWith("-") };
}

/* ------------------------------------------------------------------------ */
/* Sorting                                                                   */
/* ------------------------------------------------------------------------ */

type SortField = "title" | "status" | "assignee" | "labels" | "priority" | "progress" | "estimate" | "due" | "created" | "repo";
type SortDir = "asc" | "desc";
interface SortRule {
  field: SortField;
  dir: SortDir;
}

/** `dir` is the direction a field starts in: urgent first, soonest first, newest first. */
const SORT_FIELDS: { field: SortField; label: string; icon: LucideIcon; dir: SortDir }[] = [
  { field: "title", label: "Title", icon: List, dir: "asc" },
  { field: "status", label: "Status", icon: CircleDashed, dir: "asc" },
  { field: "assignee", label: "Assignees", icon: UsersRound, dir: "asc" },
  { field: "labels", label: "Labels", icon: Tag, dir: "asc" },
  { field: "priority", label: "Priority", icon: SignalHigh, dir: "desc" },
  { field: "progress", label: "Sub-issues progress", icon: ListTodo, dir: "desc" },
  { field: "estimate", label: "Estimate", icon: Hash, dir: "desc" },
  { field: "due", label: "Due date", icon: CalendarDays, dir: "asc" },
  { field: "created", label: "Created", icon: CalendarPlus, dir: "desc" },
  { field: "repo", label: "Repository", icon: BookMarked, dir: "asc" },
];
const sortLabel = (f: SortField) => SORT_FIELDS.find((s) => s.field === f)!.label;

function sortValue(field: SortField, c: Card, ctx: BoardCtx): string | number | null {
  switch (field) {
    case "title":
      return c.title.toLowerCase();
    case "status":
      return ctx.board.columns.findIndex((col) => col.id === c.columnId);
    case "assignee":
      return c.assigneeId ? ctx.people.get(c.assigneeId)?.name.toLowerCase() ?? null : null;
    case "labels": {
      const names = c.labelIds.map((id) => ctx.labels.get(id)?.name.toLowerCase() ?? "").sort();
      return names.length ? names.join(" ") : null;
    }
    case "priority":
      return c.priority || null;
    case "progress": {
      const p = progressOf(c, ctx.kids);
      return p ? p.done / p.total : null;
    }
    case "estimate":
      return c.estimate;
    case "due":
      return c.due ? dayNumber(c.due) : null;
    case "created":
      return Number(c.id.replace(/\D/g, "")) || 0;
    case "repo":
      return c.source ? c.source.ref.split("#")[0].toLowerCase() : null;
  }
}

/** Stable, up to two rules; empty values sort last whichever way the rule points. */
function sortCards(cards: Card[], rules: SortRule[], ctx: BoardCtx): Card[] {
  if (!rules.length) return cards;
  return [...cards].sort((a, b) => {
    for (const r of rules) {
      const va = sortValue(r.field, a, ctx);
      const vb = sortValue(r.field, b, ctx);
      if (va === vb) continue;
      if (va === null) return 1;
      if (vb === null) return -1;
      const d =
        typeof va === "number" && typeof vb === "number"
          ? va - vb
          : String(va).localeCompare(String(vb), undefined, { numeric: true });
      if (d) return r.dir === "asc" ? d : -d;
    }
    return 0;
  });
}

/* ------------------------------------------------------------------------ */
/* Grouping (columns and swimlanes)                                          */
/*                                                                           */
/* A group is a slice of the board plus the patch that puts a card in it,    */
/* so dropping a card into "High" sets its priority and dropping it into     */
/* Priya's column assigns it to her. Status groups are the real columns.    */
/* ------------------------------------------------------------------------ */

type GroupBy = "status" | "priority" | "assignee";
type Lanes = "none" | GroupBy;

interface Group {
  id: string;
  name: string;
  patch: Partial<Card>;
  match: (c: Card) => boolean;
  column?: Column;
  priority?: Priority;
  /** `null` is the Unassigned group. */
  person?: Person | null;
}

const GROUP_OPTIONS: { key: GroupBy; label: string }[] = [
  { key: "status", label: "Status" },
  { key: "priority", label: "Priority" },
  { key: "assignee", label: "Assignee" },
];

const ALL_LANE: Group = { id: "all", name: "All", patch: {}, match: () => true };

function groupsFor(by: GroupBy, board: Board): Group[] {
  if (by === "status") {
    return board.columns.map((col) => ({
      id: col.id,
      name: col.name,
      column: col,
      patch: { columnId: col.id },
      match: (c: Card) => c.columnId === col.id,
    }));
  }
  if (by === "priority") {
    return ([4, 3, 2, 1, 0] as Priority[]).map((p) => ({
      id: `p${p}`,
      name: PRIORITIES[p],
      priority: p,
      patch: { priority: p },
      match: (c: Card) => c.priority === p,
    }));
  }
  return [
    ...board.people.map((p) => ({
      id: `a:${p.id}`,
      name: p.name,
      person: p,
      patch: { assigneeId: p.id },
      match: (c: Card) => c.assigneeId === p.id,
    })),
    { id: "a:none", name: "Unassigned", person: null, patch: { assigneeId: null }, match: (c: Card) => !c.assigneeId },
  ];
}

