interface CardViewProps {
  card: Card;
  bc: BoardCtx;
  fields: Set<FieldKey>;
  grabbed?: boolean;
  hidden?: boolean;
  /** Lit while a link to this card is hovered, or just after one was followed. */
  highlighted?: boolean;
  helpId?: string;
  onPointerDown?: (e: ReactPointerEvent<HTMLDivElement>) => void;
  onOpen?: () => void;
  onKeyDown?: (e: ReactKeyboardEvent<HTMLDivElement>) => void;
  onJump?: (id: string) => void;
  onHoverLink?: (id: string | null) => void;
}

function CardView({
  card,
  bc,
  fields,
  grabbed,
  hidden,
  highlighted,
  helpId,
  onPointerDown,
  onOpen,
  onKeyDown,
  onJump,
  onHoverLink,
}: CardViewProps) {
  const person = card.assigneeId ? bc.people.get(card.assigneeId) : undefined;
  const due = dueState(card.due, card.columnId);
  const isDone = card.columnId === DONE_ID;
  const col = bc.board.columns.find((c) => c.id === card.columnId);
  const parent = card.parentId ? bc.board.cards.find((c) => c.id === card.parentId) : undefined;
  const children = bc.kids.get(card.id) ?? [];
  const progress = cardProgress(card, bc);

  // Links are buttons inside the card. They stay out of the tab order (the
  // sheet carries the same links for keyboard users) and never start a drag.
  const link = (target: Card, body: ReactNode, key: string) => (
    <button
      key={key}
      type="button"
      data-card-link
      tabIndex={-1}
      title={`${target.key} ${target.title}`}
      onPointerDown={(e) => e.stopPropagation()}
      onClick={(e) => {
        e.stopPropagation();
        onJump?.(target.id);
      }}
      onMouseEnter={() => onHoverLink?.(target.id)}
      onMouseLeave={() => onHoverLink?.(null)}
      className="inline-flex h-5 min-w-0 max-w-full items-center gap-1 rounded-full border border-stone-300/80 bg-white/70 px-1.5 text-[11px] text-stone-600 transition-colors duration-150 hover:border-stone-400 hover:text-stone-900 dark:border-stone-700 dark:bg-stone-900/60 dark:text-stone-400 dark:hover:border-stone-500 dark:hover:text-stone-100"
    >
      {body}
    </button>
  );

  return (
    <div
      data-card-id={card.id}
      role="button"
      tabIndex={0}
      aria-roledescription="draggable card"
      aria-describedby={helpId}
      aria-pressed={grabbed ? true : undefined}
      onPointerDown={onPointerDown}
      onClick={onOpen}
      onKeyDown={onKeyDown}
      style={cardVars(col?.color ?? "#a8a29e")}
      className={cn(
        "group relative flex cursor-grab select-none flex-col gap-2 rounded-xl border p-3 text-left transition-[border-color,box-shadow,opacity] duration-150",
        "border-[color:var(--card-line)] bg-[var(--card-bg)] dark:border-[color:var(--card-line-dark)] dark:bg-[var(--card-bg-dark)]",
        "[-webkit-touch-callout:none]",
        grabbed
          ? "shadow-[0_1px_2px_-1px_rgba(0,0,0,0.06),0_12px_24px_-12px_rgba(28,25,23,0.35)] ring-2 ring-emerald-600 dark:ring-emerald-400"
          : "shadow-[0_1px_2px_-1px_rgba(0,0,0,0.06)] dark:shadow-none",
        highlighted &&
          !grabbed &&
          "ring-2 ring-emerald-600/70 ring-offset-2 ring-offset-stone-50 dark:ring-emerald-400/70 dark:ring-offset-stone-950",
        hidden && "opacity-0",
        FOCUS
      )}
    >
      {(fields.has("key") || fields.has("priority")) && (
        <div className="flex items-center gap-2">
          {fields.has("key") && (
            <span className="font-[family-name:var(--font-deck-mono)] text-[11px] leading-4 text-stone-500 dark:text-stone-500">
              {card.key}
            </span>
          )}
          <span className="flex-1" />
          {fields.has("priority") && <PriorityGlyph priority={card.priority} />}
        </div>
      )}

      {fields.has("parent") && parent && (
        <div className="flex min-w-0">
          {link(
            parent,
            <>
              <CornerDownRight aria-hidden className="h-3 w-3 shrink-0" />
              <span className="sr-only">Sub-issue of</span>
              <span className="shrink-0 font-[family-name:var(--font-deck-mono)]">{parent.key}</span>
              <span className="truncate">{parent.title}</span>
            </>,
            "parent"
          )}
        </div>
      )}

      <p
        className={cn(
          "line-clamp-3 text-sm font-medium leading-5 text-stone-900 dark:text-stone-100",
          isDone && "text-stone-600 dark:text-stone-400"
        )}
      >
        {card.title}
      </p>

      {fields.has("labels") && card.labelIds.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {card.labelIds.map((id) => {
            const l = bc.labels.get(id);
            return l ? (
              <LabelChip key={id} color={l.color} size="sm">
                {l.name}
              </LabelChip>
            ) : null;
          })}
        </div>
      )}

      {fields.has("progress") && <ProgressMeter p={progress} />}

      {fields.has("parent") && children.length > 0 && (
        <div className="flex min-w-0 flex-wrap items-center gap-1">
          <span className="text-[11px] text-stone-500">Sub-issues</span>
          {children.slice(0, 4).map((ch) =>
            link(
              ch,
              <>
                <Dot color={bc.board.columns.find((c) => c.id === ch.columnId)?.color ?? "#a8a29e"} />
                <span className={cn("font-[family-name:var(--font-deck-mono)]", ch.columnId === DONE_ID && "line-through")}>
                  {ch.key}
                </span>
              </>,
              ch.id
            )
          )}
          {children.length > 4 && <span className="text-[11px] text-stone-500">+{children.length - 4}</span>}
        </div>
      )}

      {((fields.has("due") && card.due) ||
        (fields.has("estimate") && card.estimate !== null) ||
        (fields.has("assignee") && person)) && (
        <div className="flex min-h-6 items-center gap-3 text-xs text-stone-500 dark:text-stone-500">
          {fields.has("due") && card.due && (
            <span
              className={cn(
                "inline-flex items-center gap-1 tabular-nums",
                due === "overdue" && "font-medium text-red-700 dark:text-red-400",
                due === "soon" && "font-medium text-amber-700 dark:text-amber-400"
              )}
            >
              <CalendarDays aria-hidden className="h-3.5 w-3.5" />
              <span className="sr-only">{due === "overdue" ? "Overdue, due" : "Due"}</span>
              {shortDate(card.due)}
            </span>
          )}
          {fields.has("estimate") && card.estimate !== null && (
            <span className="inline-flex h-5 items-center rounded-full bg-stone-900/5 px-1.5 text-[11px] tabular-nums text-stone-600 dark:bg-white/10 dark:text-stone-400">
              {card.estimate} pt{card.estimate === 1 ? "" : "s"}
            </span>
          )}
          <span className="flex-1" />
          {fields.has("assignee") && person && <Initials person={person} size="xs" />}
        </div>
      )}
    </div>
  );
}

