function AutoTextarea({
  value,
  onChange,
  className,
  inputRef,
  ...rest
}: {
  value: string;
  onChange: (v: string) => void;
  inputRef?: React.RefObject<HTMLTextAreaElement | null>;
} & Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, "value" | "onChange">) {
  const ref = useRef<HTMLTextAreaElement>(null);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = "0px";
    el.style.height = el.scrollHeight + "px";
  }, [value]);
  return (
    <textarea
      ref={(el) => {
        ref.current = el;
        if (inputRef) inputRef.current = el;
      }}
      rows={1}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      className={cn("block w-full resize-none overflow-hidden bg-transparent outline-none", className)}
      {...rest}
    />
  );
}

function FieldRow({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="grid grid-cols-[96px_1fr] items-center gap-3">
      <span className="text-xs text-stone-500 dark:text-stone-500">{label}</span>
      <div className="min-w-0">{children}</div>
    </div>
  );
}

interface CardFieldsProps {
  card: Card;
  board: Board;
  swatches: string[];
  patch: (p: Partial<Card>) => void;
  createLabel: (name: string, color: string) => string;
  createColumn: (name: string, color: string) => string;
  recolor: Recolor;
  titleRef?: React.RefObject<HTMLTextAreaElement | null>;
}

interface Recolor {
  column: (id: string, hex: string) => void;
  label: (id: string, hex: string) => void;
}

function CardFields({ card, board, swatches, patch, createLabel, createColumn, recolor, titleRef }: CardFieldsProps) {
  const [addingColumn, setAddingColumn] = useState(false);
  const labelMap = useMemo(() => new Map(board.labels.map((l) => [l.id, l])), [board.labels]);
  const kids = useMemo(() => childrenOf(board.cards), [board.cards]);
  // A card cannot sit under itself or anything beneath it.
  const parentOptions = useMemo(() => {
    const family = familyOf(card.id, kids);
    return board.cards.filter((c) => !family.has(c.id));
  }, [board.cards, card.id, kids]);
  const colIndex = Math.max(
    0,
    board.columns.findIndex((c) => c.id === card.columnId)
  );
  const col = board.columns[colIndex];

  return (
    <div className="flex flex-col gap-6">
      <AutoTextarea
        inputRef={titleRef}
        value={card.title}
        onChange={(v) => patch({ title: v.replace(/\n/g, " ") })}
        aria-label="Title"
        placeholder="Card title"
        className="text-lg font-semibold leading-7 tracking-tight text-stone-900 placeholder:text-stone-400 dark:text-stone-100 dark:placeholder:text-stone-600"
      />

      <div className="flex flex-col gap-3">
        <FieldRow label="Status">
          <div className="flex items-center gap-2">
            {col && (
              <ColorPicker
                value={col.color}
                onChange={(hex) => recolor.column(col.id, hex)}
                label={`${col.name} column colour`}
                swatches={swatches}
                triggerClassName={cn(
                  "h-8 w-8 shrink-0 rounded-md ring-1 ring-inset ring-black/10 transition-shadow duration-150 hover:ring-2 hover:ring-black/20 dark:ring-white/15 dark:hover:ring-white/30",
                  FOCUS
                )}
              />
            )}
            <Select
              size="sm"
              className="w-full"
              label="Status"
              options={[...board.columns.map((c) => c.name), "+ New column"]}
              value={colIndex}
              onChange={(i) => {
                if (i === board.columns.length) setAddingColumn(true);
                else patch({ columnId: board.columns[i].id });
              }}
            />
          </div>
          <AnimatePresence initial={false}>
            {addingColumn && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0, transition: { duration: 0.12 } }}
                transition={{ duration: 0.2, ease: EASE_OUT }}
                className="overflow-hidden"
              >
                <div className="pt-2">
                  <NewColumnForm
                    compact
                    swatches={swatches}
                    onCancel={() => setAddingColumn(false)}
                    onCreate={(name, color) => {
                      patch({ columnId: createColumn(name, color) });
                      setAddingColumn(false);
                    }}
                  />
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </FieldRow>

        <FieldRow label="Priority">
          <Select
            size="sm"
            className="w-full"
            label="Priority"
            icon={<PriorityGlyph priority={card.priority} />}
            options={[...PRIORITIES]}
            value={card.priority}
            onChange={(i) => patch({ priority: i as Priority })}
          />
        </FieldRow>

        <FieldRow label="Assignee">
          <Select
            size="sm"
            className="w-full"
            label="Assignee"
            options={["Unassigned", ...board.people.map((p) => p.name)]}
            value={card.assigneeId ? board.people.findIndex((p) => p.id === card.assigneeId) + 1 : 0}
            onChange={(i) => patch({ assigneeId: i === 0 ? null : board.people[i - 1].id })}
          />
        </FieldRow>

        <FieldRow label="Dates">
          <div className="grid grid-cols-2 gap-2">
            <input
              type="date"
              value={card.start ?? ""}
              max={card.due ?? undefined}
              onChange={(e) => patch({ start: e.target.value || null })}
              aria-label="Start date"
              className={cn(INPUT, "h-8 w-full px-2 text-xs tabular-nums [color-scheme:light] dark:[color-scheme:dark]")}
            />
            <input
              type="date"
              value={card.due ?? ""}
              min={card.start ?? undefined}
              onChange={(e) => patch({ due: e.target.value || null })}
              aria-label="Due date"
              className={cn(INPUT, "h-8 w-full px-2 text-xs tabular-nums [color-scheme:light] dark:[color-scheme:dark]")}
            />
          </div>
        </FieldRow>

        <FieldRow label="Estimate">
          <input
            type="number"
            min={0}
            max={99}
            inputMode="numeric"
            value={card.estimate ?? ""}
            placeholder="Points"
            onChange={(e) =>
              patch({ estimate: e.target.value === "" ? null : Math.max(0, Math.min(99, Number(e.target.value))) })
            }
            aria-label="Estimate in story points"
            className={cn(INPUT, "h-8 w-24 text-xs tabular-nums")}
          />
        </FieldRow>

        <FieldRow label="Parent">
          <Select
            size="sm"
            className="w-full"
            label="Parent issue"
            options={["No parent", ...parentOptions.map((c) => `${c.key} ${c.title}`)]}
            value={card.parentId ? parentOptions.findIndex((c) => c.id === card.parentId) + 1 : 0}
            onChange={(i) => patch({ parentId: i === 0 ? null : parentOptions[i - 1].id })}
          />
        </FieldRow>

        <FieldRow label="Labels">
          <div className="flex flex-wrap items-center gap-1.5">
            {card.labelIds.map((id) => {
              const l = labelMap.get(id);
              return l ? (
                <LabelChip key={id} color={l.color} onRemove={() => patch({ labelIds: card.labelIds.filter((x) => x !== id) })}>
                  {l.name}
                </LabelChip>
              ) : null;
            })}
            <LabelMenu
              labels={board.labels}
              selected={new Set(card.labelIds)}
              swatches={swatches}
              onToggle={(id) =>
                patch({ labelIds: card.labelIds.includes(id) ? card.labelIds.filter((x) => x !== id) : [...card.labelIds, id] })
              }
              onCreate={(name, color) => patch({ labelIds: [...card.labelIds, createLabel(name, color)] })}
              onRecolor={recolor.label}
              trigger={({ open, toggle }) => (
                <button
                  type="button"
                  aria-expanded={open}
                  onClick={toggle}
                  className={cn(
                    "inline-flex h-6 items-center gap-1 rounded-full border border-dashed border-stone-300 px-2 text-xs text-stone-600 transition-colors duration-150 hover:border-stone-400 hover:text-stone-900 dark:border-stone-700 dark:text-stone-400 dark:hover:border-stone-500 dark:hover:text-stone-100",
                    FOCUS
                  )}
                >
                  <Plus aria-hidden className="h-3 w-3" /> Label
                </button>
              )}
            />
          </div>
        </FieldRow>
      </div>

      <div className="flex flex-col gap-2">
        <span className={EYEBROW}>Description</span>
        <AutoTextarea
          value={card.description}
          onChange={(v) => patch({ description: v })}
          aria-label="Description"
          placeholder="Add the context someone picking this up would need."
          className={cn(INPUT, "min-h-24 py-2 leading-6")}
        />
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Overlays                                                                  */
/* ------------------------------------------------------------------------ */

/** Keeps Tab inside `ref`, and hands focus back to whatever opened it. */
function useFocusTrap(ref: React.RefObject<HTMLElement | null>, initial?: React.RefObject<HTMLElement | null>) {
  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null;
    const el = ref.current;
    (initial?.current ?? el)?.focus({ preventScroll: true });
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Tab" || !el) return;
      const f = Array.from(
        el.querySelectorAll<HTMLElement>('button:not([disabled]), input, textarea, select, [tabindex]:not([tabindex="-1"])')
      ).filter((n) => n.offsetParent !== null);
      if (!f.length) return;
      const first = f[0];
      const last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };
    el?.addEventListener("keydown", onKey);
    return () => {
      el?.removeEventListener("keydown", onKey);
      opener?.focus?.({ preventScroll: true });
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
}

/** Escape closes, unless a picker or listbox inside is the thing that is open. */
function useEscape(onClose: () => void) {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      if (document.querySelector("[data-color-picker]")) return;
      if ((document.activeElement as HTMLElement | null)?.getAttribute("aria-expanded") === "true") return;
      onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
}

