/* ------------------------------------------------------------------------ */
/* GitHub import                                                             */
/*                                                                           */
/* Reads a repo's issues from GitHub's REST API in the browser. Public repos */
/* need nothing; a token (kept in memory, never stored) opens private ones   */
/* and lifts the signed-out limit of 60 requests an hour.                    */
/* ------------------------------------------------------------------------ */

interface GhIssue {
  id: number;
  number: number;
  title: string;
  body: string | null;
  state: "open" | "closed";
  html_url: string;
  labels: Array<string | { name?: string; color?: string }>;
  assignee: { login: string; avatar_url: string } | null;
  milestone: { due_on: string | null } | null;
  created_at: string;
  closed_at: string | null;
  sub_issues_summary?: { total: number; completed: number };
  pull_request?: unknown;
}

function GithubMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 16 16" aria-hidden className={className} fill="currentColor">
      <path d="M8 0c4.42 0 8 3.58 8 8a8.013 8.013 0 0 1-5.45 7.59c-.4.08-.55-.17-.55-.38 0-.27.01-1.13.01-2.2 0-.75-.25-1.23-.54-1.48 1.78-.2 3.65-.88 3.65-3.95 0-.88-.31-1.59-.82-2.15.08-.2.36-1.02-.08-2.12 0 0-.67-.22-2.2.82-.64-.18-1.32-.27-2-.27-.68 0-1.36.09-2 .27-1.53-1.03-2.2-.82-2.2-.82-.44 1.1-.16 1.92-.08 2.12-.51.56-.82 1.28-.82 2.15 0 3.06 1.86 3.75 3.64 3.95-.23.2-.44.55-.51 1.07-.46.21-1.61.55-2.33-.66-.15-.24-.6-.83-1.23-.82-.67.01-.27.38.01.53.34.19.73.9.82 1.13.16.45.68 1.31 2.69.94 0 .67.01 1.3.01 1.49 0 .21-.15.45-.55.38A7.995 7.995 0 0 1 0 8c0-4.42 3.58-8 8-8Z" />
    </svg>
  );
}

/** "owner/repo", or any github.com URL inside the repo. */
function parseRepo(input: string): string | null {
  const m = input.trim().match(/^(?:https?:\/\/)?(?:www\.)?(?:github\.com\/)?([\w.-]+)\/([\w.-]+?)(?:\.git)?(?:[/?#].*)?$/i);
  return m ? `${m[1]}/${m[2]}` : null;
}

const TASK_RE = /^\s*[-*]\s+\[( |x|X)\]\s+(.+)$/gm;

function priorityFromLabels(names: string[]): Priority {
  const t = names.join(" ").toLowerCase();
  if (/\b(urgent|critical|blocker|p0)\b/.test(t)) return 4;
  if (/\b(high|p1)\b/.test(t)) return 3;
  if (/\b(medium|p2)\b/.test(t)) return 2;
  if (/\b(low|p3)\b/.test(t)) return 1;
  return 0;
}

/** Imported assignees take the next rung of the same ladder the seed team uses. */
const IMPORT_LADDER = ["bg-emerald-900", "bg-amber-900", "bg-stone-700", "bg-emerald-700", "bg-amber-700"];

/** A task-list line that points at another issue: "- [ ] #123" or "- [x] Fix it (#123)". */
const ISSUE_REF_RE = /(?:^|[\s(])#(\d+)\b/;

/**
 * Issues become cards; a task list inside an issue becomes sub-issue cards
 * under it, and a task line that names another issue links that issue's card
 * as a sub-issue instead of duplicating it. GitHub's own sub-issue count is
 * kept for a parent whose children were not imported.
 */
function importIssues(b: Board, repo: string, issues: GhIssue[], openCol: string): { board: Board; added: number } {
  const labels = [...b.labels];
  const people = [...b.people];
  let cards = [...b.cards];
  let seq = b.seq;
  let added = 0;
  const doneCol = b.columns.some((c) => c.id === DONE_ID) ? DONE_ID : openCol;
  const links: { parentRef: string; childRef: string }[] = [];

  for (const issue of issues) {
    const ref = `${repo}#${issue.number}`;
    if (cards.some((c) => c.source?.ref === ref)) continue;
    seq += 1;
    const id = `n${seq}`;

    const ghLabels = issue.labels
      .map((l) => (typeof l === "string" ? { name: l, color: undefined } : l))
      .filter((l): l is { name: string; color?: string } => !!l.name);
    const labelIds = ghLabels.map((l) => {
      const found = labels.find((x) => x.name.toLowerCase() === l.name.toLowerCase());
      if (found) return found.id;
      const lid = `gh-${seq}-${labels.length}`;
      labels.push({ id: lid, name: l.name, color: l.color ? `#${l.color}` : "#78716c" });
      return lid;
    });

    let assigneeId: string | null = null;
    if (issue.assignee) {
      assigneeId = `gh:${issue.assignee.login}`;
      if (!people.some((p) => p.id === assigneeId)) {
        people.push({
          id: assigneeId,
          name: issue.assignee.login,
          initials: issue.assignee.login.slice(0, 2).toUpperCase(),
          role: "GitHub",
          color: IMPORT_LADDER[people.length % IMPORT_LADDER.length],
          avatarUrl: `${issue.assignee.avatar_url}${issue.assignee.avatar_url.includes("?") ? "&" : "?"}s=64`,
        });
      }
    }

    const body = issue.body ?? "";
    const tasks = Array.from(body.matchAll(TASK_RE)).map((m) => ({ text: m[2].trim(), done: m[1] !== " " }));
    const description = body
      .replace(TASK_RE, "")
      .replace(/\n{3,}/g, "\n\n")
      .trim()
      .slice(0, 1200);
    const columnId = issue.state === "closed" ? doneCol : openCol;
    const summary = issue.sub_issues_summary;

    const card: Card = {
      id,
      key: `#${issue.number}`,
      title: issue.title,
      description,
      columnId,
      labelIds,
      assigneeId,
      priority: priorityFromLabels(ghLabels.map((l) => l.name)),
      estimate: null,
      start: null,
      due: issue.milestone?.due_on?.slice(0, 10) ?? null,
      parentId: null,
      createdAt: issue.created_at?.slice(0, 10) ?? TODAY,
      closedAt: issue.closed_at?.slice(0, 10) ?? null,
      remoteProgress: summary && summary.total > 0 ? { done: summary.completed, total: summary.total } : undefined,
      activity: [{ id: `${id}a0`, text: `Imported from ${ref}`, at: shortDate(TODAY) }],
      source: { url: issue.html_url, ref },
    };
    cards = moveCard([...cards, card], id, columnId, null);
    added += 1;

    tasks.forEach((t, j) => {
      const m = t.text.match(ISSUE_REF_RE);
      if (m) {
        links.push({ parentRef: ref, childRef: `${repo}#${m[1]}` });
        return;
      }
      const cid = `${id}t${j}`;
      const col = t.done ? doneCol : columnId === doneCol ? openCol : columnId;
      const child: Card = {
        ...card,
        id: cid,
        key: `#${issue.number}.${j + 1}`,
        title: t.text,
        description: "",
        columnId: col,
        priority: 0,
        due: null,
        parentId: id,
        closedAt: t.done ? card.closedAt ?? TODAY : null,
        remoteProgress: undefined,
        activity: [{ id: `${cid}a0`, text: `From the task list on ${ref}`, at: shortDate(TODAY) }],
        source: undefined,
      };
      cards = moveCard([...cards, child], cid, col, null);
      added += 1;
    });
  }

  for (const { parentRef, childRef } of links) {
    const parent = cards.find((c) => c.source?.ref === parentRef);
    const child = cards.find((c) => c.source?.ref === childRef);
    if (parent && child && !child.parentId && child.id !== parent.id) {
      cards = cards.map((c) => (c.id === child.id ? { ...c, parentId: parent.id } : c));
    }
  }
  return { board: { ...b, labels, people, cards, seq }, added };
}

type Fetched = { repo: string; issues: GhIssue[] };

function GithubImportDialog({
  board,
  onImport,
  onClose,
}: {
  board: Board;
  onImport: (repo: string, issues: GhIssue[], column: string) => void;
  onClose: () => void;
}) {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const headingId = useId();
  useFocusTrap(ref, inputRef);
  useEscape(onClose);

  const [repoText, setRepoText] = useState("");
  const [token, setToken] = useState("");
  const [showToken, setShowToken] = useState(false);
  const [includeClosed, setIncludeClosed] = useState(false);
  const [col, setCol] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [fetched, setFetched] = useState<Fetched | null>(null);
  const [picked, setPicked] = useState<Set<number>>(() => new Set());
  const abort = useRef<AbortController | null>(null);
  useEffect(() => () => abort.current?.abort(), []);

  const onBoard = useMemo(() => new Set(board.cards.map((c) => c.source?.ref).filter(Boolean)), [board.cards]);

  const load = async () => {
    const repo = parseRepo(repoText);
    if (!repo) {
      setError("Use owner/repo, for example facebook/react, or paste the repo's URL.");
      return;
    }
    abort.current?.abort();
    const ctl = new AbortController();
    abort.current = ctl;
    setLoading(true);
    setError(null);
    setFetched(null);
    try {
      const res = await fetch(
        `https://api.github.com/repos/${repo}/issues?state=${includeClosed ? "all" : "open"}&per_page=50&sort=updated`,
        {
          signal: ctl.signal,
          headers: {
            Accept: "application/vnd.github+json",
            ...(token.trim() ? { Authorization: `Bearer ${token.trim()}` } : {}),
          },
        }
      );
      if (!res.ok) {
        if (res.status === 404)
          throw new Error(`No repo called ${repo} that this ${token ? "token" : "browser"} can see. Private repos need a token.`);
        if (res.status === 401) throw new Error("GitHub did not accept that token.");
        if ((res.status === 403 || res.status === 429) && res.headers.get("x-ratelimit-remaining") === "0") {
          const reset = Number(res.headers.get("x-ratelimit-reset")) * 1000;
          const when = reset ? new Date(reset).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }) : "later";
          throw new Error(
            `GitHub allows 60 signed-out requests an hour and they are spent. Add a token, or try again after ${when}.`
          );
        }
        throw new Error(`GitHub answered ${res.status}. Try again in a moment.`);
      }
      const issues = ((await res.json()) as GhIssue[]).filter((i) => !i.pull_request);
      setFetched({ repo, issues });
      setPicked(new Set(issues.filter((i) => !onBoard.has(`${repo}#${i.number}`)).map((i) => i.id)));
    } catch (e) {
      if ((e as Error).name === "AbortError") return;
      setError((e as Error).message || "Could not reach GitHub.");
    } finally {
      if (abort.current === ctl) setLoading(false);
    }
  };

  const fresh = fetched?.issues.filter((i) => !onBoard.has(`${fetched.repo}#${i.number}`)) ?? [];
  const chosen = fresh.filter((i) => picked.has(i.id));
  const allOn = fresh.length > 0 && chosen.length === fresh.length;

  return (
    <div
      className="pointer-events-auto absolute inset-0 z-40 flex items-start justify-center overflow-y-auto overscroll-contain p-4 pt-12 sm:pt-16"
      data-lenis-prevent
    >
      <motion.div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={headingId}
        initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.96, y: 8 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.98, transition: { duration: 0.14, ease: EASE_OUT } }}
        transition={{ duration: 0.24, ease: EASE_OUT }}
        className="relative flex max-h-[calc(100%-32px)] w-full max-w-lg flex-col rounded-2xl border border-stone-200 bg-white ring-1 ring-stone-900/5 shadow-[0_1px_2px_-1px_rgba(0,0,0,0.06),0_24px_48px_-16px_rgba(28,25,23,0.25)] dark:border-stone-800 dark:bg-stone-900 dark:ring-white/10 dark:shadow-none"
      >
        <div className="flex shrink-0 items-center gap-2 border-b border-stone-200 px-5 py-3 dark:border-stone-800">
          <GithubMark className="h-4 w-4 text-stone-900 dark:text-stone-100" />
          <h2 id={headingId} className="text-sm font-medium text-stone-900 dark:text-stone-100">
            Import issues from GitHub
          </h2>
          <span className="flex-1" />
          <button type="button" onClick={onClose} className={ICON_BTN} aria-label="Close">
            <X aria-hidden className="h-4 w-4" />
          </button>
        </div>

        <form
          className="flex shrink-0 flex-col gap-3 px-5 pt-5"
          onSubmit={(e) => {
            e.preventDefault();
            void load();
          }}
        >
          <div className="flex gap-2">
            <input
              ref={inputRef}
              value={repoText}
              onChange={(e) => setRepoText(e.target.value)}
              placeholder="owner/repo"
              aria-label="Repository"
              spellCheck={false}
              autoCapitalize="off"
              className={cn(INPUT, "h-9 min-w-0 flex-1 font-[family-name:var(--font-deck-mono)] text-xs")}
            />
            <button type="submit" disabled={loading || !repoText.trim()} className={PRIMARY}>
              {loading ? <LoaderCircle aria-hidden className="h-4 w-4 animate-spin motion-reduce:animate-none" /> : null}
              {loading ? "Fetching" : "Fetch issues"}
            </button>
          </div>
          <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-xs text-stone-600 dark:text-stone-400">
            <label className="inline-flex cursor-pointer items-center gap-2">
              <input
                type="checkbox"
                checked={includeClosed}
                onChange={(e) => setIncludeClosed(e.target.checked)}
                className="h-4 w-4 rounded accent-emerald-700"
              />
              Include closed (they land in Done)
            </label>
            <button
              type="button"
              onClick={() => setShowToken((v) => !v)}
              aria-expanded={showToken}
              className={cn("underline-offset-2 hover:underline", FOCUS)}
            >
              {showToken ? "Hide token" : "Private repo? Add a token"}
            </button>
          </div>
          {showToken && (
            <div className="flex flex-col gap-1">
              <input
                type="password"
                value={token}
                onChange={(e) => setToken(e.target.value)}
                placeholder="github_pat_..."
                aria-label="GitHub token"
                autoComplete="off"
                className={cn(INPUT, "h-8 font-[family-name:var(--font-deck-mono)] text-xs")}
              />
              <span className="text-[11px] leading-4 text-stone-500">
                A fine-grained token with read access to issues. It stays in this tab&apos;s memory and is sent only to
                api.github.com.
              </span>
            </div>
          )}
        </form>

        <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 py-4" data-lenis-prevent aria-live="polite">
          {error && (
            <p
              role="alert"
              className="rounded-lg border border-stone-300 bg-stone-100 px-3 py-2 text-xs leading-5 text-stone-700 dark:border-stone-700 dark:bg-stone-950 dark:text-stone-300"
            >
              {error}
            </p>
          )}
          {fetched && fetched.issues.length === 0 && (
            <p className="py-6 text-center text-sm text-stone-500">
              No {includeClosed ? "" : "open "}issues in {fetched.repo}.
            </p>
          )}
          {fetched && fetched.issues.length > 0 && (
            <div className="flex flex-col gap-2">
              <div className="flex items-center gap-2">
                <span className={EYEBROW}>{fetched.repo}</span>
                <span className="text-xs tabular-nums text-stone-500">
                  {chosen.length} of {fresh.length} selected
                </span>
                <span className="flex-1" />
                {fresh.length > 0 && (
                  <button
                    type="button"
                    onClick={() => setPicked(allOn ? new Set() : new Set(fresh.map((i) => i.id)))}
                    className={cn("text-xs text-stone-600 underline-offset-2 hover:underline dark:text-stone-400", FOCUS)}
                  >
                    {allOn ? "Select none" : "Select all"}
                  </button>
                )}
              </div>
              <ul className="flex flex-col divide-y divide-stone-200 rounded-xl border border-stone-200 dark:divide-stone-800 dark:border-stone-800">
                {fetched.issues.map((i) => {
                  const already = onBoard.has(`${fetched.repo}#${i.number}`);
                  return (
                    <li key={i.id}>
                      <label
                        className={cn(
                          "flex items-start gap-3 px-3 py-2.5",
                          already ? "opacity-60" : "cursor-pointer hover:bg-stone-50 dark:hover:bg-stone-800/60"
                        )}
                      >
                        <input
                          type="checkbox"
                          disabled={already}
                          checked={already || picked.has(i.id)}
                          onChange={() =>
                            setPicked((s) => {
                              const next = new Set(s);
                              if (next.has(i.id)) next.delete(i.id);
                              else next.add(i.id);
                              return next;
                            })
                          }
                          className="mt-0.5 h-4 w-4 shrink-0 rounded accent-emerald-700"
                        />
                        <span className="min-w-0 flex-1">
                          <span className="block text-sm leading-5 text-stone-900 dark:text-stone-100">{i.title}</span>
                          <span className="mt-0.5 flex items-center gap-2 text-xs text-stone-500">
                            <span className="font-[family-name:var(--font-deck-mono)]">#{i.number}</span>
                            <span
                              className={cn(
                                "inline-flex items-center gap-1",
                                i.state === "open" ? "text-green-700 dark:text-green-400" : "text-stone-500"
                              )}
                            >
                              <span
                                aria-hidden
                                className={cn("h-1.5 w-1.5 rounded-full", i.state === "open" ? "bg-green-600" : "bg-stone-400")}
                              />
                              {i.state === "open" ? "Open" : "Closed"}
                            </span>
                            {already && <span>On the board</span>}
                          </span>
                        </span>
                      </label>
                    </li>
                  );
                })}
              </ul>
            </div>
          )}
          {!fetched && !error && (
            <p className="py-4 text-xs leading-5 text-stone-500">
              Labels come across in their GitHub colours, the milestone&apos;s due date becomes the card&apos;s, and each
              task-list item becomes a sub-issue card (or links the issue it names). Issues already on the board are skipped.
            </p>
          )}
        </div>

        <div className="flex shrink-0 flex-wrap items-center gap-2 border-t border-stone-200 px-5 py-3 dark:border-stone-800">
          <span className="text-xs text-stone-500">Open issues go to</span>
          <Select
            size="sm"
            label="Column for open issues"
            options={board.columns.map((c) => c.name)}
            value={Math.min(col, board.columns.length - 1)}
            onChange={setCol}
          />
          <span className="flex-1" />
          <button type="button" onClick={onClose} className={GHOST}>
            Cancel
          </button>
          <button
            type="button"
            disabled={chosen.length === 0}
            onClick={() => fetched && onImport(fetched.repo, chosen, board.columns[Math.min(col, board.columns.length - 1)].id)}
            className={PRIMARY}
          >
            Import {chosen.length > 0 ? chosen.length : ""} {chosen.length === 1 ? "card" : "cards"}
          </button>
        </div>
      </motion.div>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Progress and status tint                                                  */
/* ------------------------------------------------------------------------ */

/** A card's fill and border, tinted with its status column's colour in CSS. */
function cardVars(color: string): CSSProperties {
  return {
    "--card-bg": `color-mix(in oklab, ${color} 7%, #ffffff)`,
    "--card-line": `color-mix(in oklab, ${color} 34%, #ffffff)`,
    "--card-bg-dark": `color-mix(in oklab, ${color} 11%, #1c1917)`,
    "--card-line-dark": `color-mix(in oklab, ${color} 40%, #1c1917)`,
  } as CSSProperties;
}

interface CardProgress {
  value: number;
  label: string;
  items: Progress | null;
  complete: boolean;
  text: string;
}

/**
 * Every card gets a reading. Its sub-issues when it has any;
 * otherwise how far along the columns it has travelled, so a card with no
 * breakdown still shows where it stands.
 */
function cardProgress(card: Card, ctx: BoardCtx): CardProgress {
  const items = progressOf(card, ctx.kids);
  if (items) {
    return {
      value: items.done / items.total,
      label: `${items.done}/${items.total}`,
      items,
      complete: items.done === items.total,
      text: `${items.done} of ${items.total} sub-issues done`,
    };
  }
  const cols = ctx.board.columns;
  const i = Math.max(
    0,
    cols.findIndex((c) => c.id === card.columnId)
  );
  const value = card.columnId === DONE_ID ? 1 : cols.length > 1 ? i / (cols.length - 1) : 0;
  const pct = Math.round(value * 100);
  return { value, label: `${pct}%`, items: null, complete: value === 1, text: `${pct} percent of the way through the columns` };
}

function ProgressMeter({ p, className }: { p: CardProgress; className?: string }) {
  const segs = p.items && p.items.total <= 12 ? p.items.total : 0;
  const fill = p.complete ? "bg-green-600" : "bg-emerald-700 dark:bg-emerald-500";
  return (
    <div
      className={cn("flex items-center gap-2", className)}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(p.value * 100)}
      aria-label={p.text}
    >
      {segs ? (
        <div className="flex h-1.5 min-w-0 flex-1 gap-0.5" aria-hidden>
          {Array.from({ length: segs }, (_, i) => (
            <span key={i} className={cn("flex-1 rounded-full", i < p.items!.done ? fill : "bg-stone-200 dark:bg-stone-700")} />
          ))}
        </div>
      ) : (
        <div className="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-stone-200 dark:bg-stone-700" aria-hidden>
          <div
            className={cn("h-full origin-left rounded-full transition-transform duration-300", fill)}
            style={{ transform: `scaleX(${p.value})` }}
          />
        </div>
      )}
      <span
        className={cn(
          "shrink-0 text-[11px] leading-4 tabular-nums",
          p.complete ? "text-green-700 dark:text-green-400" : "text-stone-500"
        )}
      >
        {p.label}
      </span>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Filter bar                                                                */
/* ------------------------------------------------------------------------ */

interface QItem {
  kind: "field" | "value";
  insert: string;
  label: string;
  hint?: string;
  adorn?: ReactNode;
  disabled?: boolean;
}

const Dot = ({ color }: { color: string }) => (
  <span
    aria-hidden
    className="h-2.5 w-2.5 shrink-0 rounded-full ring-1 ring-inset ring-black/15 dark:ring-white/20"
    style={{ background: color }}
  />
);

function suggestionsFor(c: QContext | null, bc: BoardCtx, hasRepos: boolean): QItem[] {
  if (!c) return [];
  const pre = c.prefix.toLowerCase();
  if (c.kind === "field") {
    return Q_FIELDS.filter(
      (f) => (f.key !== "repo" || hasRepos) && (!pre || f.key.startsWith(pre) || f.label.toLowerCase().startsWith(pre))
    ).map((f) => {
      const Icon = f.icon;
      return {
        kind: "field" as const,
        insert: `${c.neg ? "-" : ""}${f.key}:`,
        label: f.label,
        hint: f.hint,
        adorn: <Icon aria-hidden className="h-4 w-4 shrink-0 text-stone-500" />,
      };
    });
  }

  const count = (pred: (card: Card) => boolean) => String(bc.board.cards.filter(pred).length);
  let values: { value: string; label: string; hint?: string; adorn?: ReactNode; disabled?: boolean }[] = [];
  switch (c.field) {
    case "is":
      values = [
        { value: "open", label: "open", hint: "not in Done" },
        { value: "done", label: "done", hint: "in Done" },
        { value: "overdue", label: "overdue", hint: "past due" },
        { value: "due-soon", label: "due-soon", hint: "within 2 days" },
        { value: "assigned", label: "assigned" },
        { value: "unassigned", label: "unassigned" },
        { value: "parent", label: "parent", hint: "has sub-issues" },
        { value: "sub-issue", label: "sub-issue", hint: "has a parent" },
        ...(hasRepos ? [{ value: "imported", label: "imported", hint: "from GitHub" }] : []),
      ];
      break;
    case "assignee":
      values = [
        ...bc.board.people.map((p) => ({
          value: handleOf(p),
          label: p.name,
          hint: count((card) => card.assigneeId === p.id),
          adorn: <Initials person={p} size="xs" />,
        })),
        { value: "none", label: "No assignee", hint: count((card) => !card.assigneeId) },
      ];
      break;
    case "label":
      values = bc.board.labels.map((l) => ({
        value: l.name,
        label: l.name,
        hint: count((card) => card.labelIds.includes(l.id)),
        adorn: <Dot color={l.color} />,
      }));
      break;
    case "status":
      values = bc.board.columns.map((col) => ({
        value: col.name,
        label: col.name,
        hint: count((card) => card.columnId === col.id),
        adorn: <Dot color={col.color} />,
      }));
      break;
    case "priority":
      values = ([4, 3, 2, 1, 0] as Priority[]).map((p) => ({
        value: PRIORITY_KEYS[p],
        label: PRIORITIES[p],
        hint: count((card) => card.priority === p),
        adorn: <PriorityGlyph priority={p} />,
      }));
      break;
    case "due":
      values = [
        { value: "overdue", label: "overdue" },
        { value: "today", label: "today" },
        { value: "this-week", label: "this-week", hint: "next 7 days" },
        { value: "next-week", label: "next-week" },
        { value: "none", label: "none", hint: "no due date" },
      ];
      break;
    case "parent":
      values = [
        ...bc.board.cards
          .filter((card) => (bc.kids.get(card.id)?.length ?? 0) > 0)
          .map((card) => ({ value: card.key, label: `${card.key} ${card.title}`, hint: String(bc.kids.get(card.id)!.length) })),
        { value: "none", label: "No parent" },
      ];
      break;
    case "title":
      values = [{ value: "", label: "Type words from the title", disabled: true }];
      break;
    case "repo":
      values = Array.from(new Set(bc.board.cards.map((card) => card.source?.ref.split("#")[0]).filter(Boolean) as string[])).map(
        (r) => ({ value: r, label: r })
      );
      break;
  }
  return values
    .filter((v) => v.disabled || !pre || v.value.toLowerCase().includes(pre) || v.label.toLowerCase().includes(pre))
    .map((v) => ({
      kind: "value" as const,
      insert: quoteValue(v.value),
      label: v.label,
      hint: v.hint,
      adorn: v.adorn,
      disabled: v.disabled,
    }));
}

/** The query drawn behind a transparent input, so qualifiers read as tokens. */
function highlightQuery(q: string, tokens: QToken[]): ReactNode[] {
  const out: ReactNode[] = [];
  let pos = 0;
  tokens.forEach((t, i) => {
    if (t.start > pos) out.push(q.slice(pos, t.start));
    if (t.field) {
      out.push(
        <span key={`k${i}`} className={t.neg ? "text-red-700 dark:text-red-400" : "text-stone-600 dark:text-stone-400"}>
          {q.slice(t.start, t.keyEnd)}
        </span>
      );
      if (t.end > t.keyEnd) {
        out.push(
          <span
            key={`v${i}`}
            className="rounded-sm bg-emerald-500/15 text-emerald-800 dark:bg-emerald-400/15 dark:text-emerald-300"
          >
            {q.slice(t.keyEnd, t.end)}
          </span>
        );
      }
    } else {
      out.push(<span key={`t${i}`}>{q.slice(t.start, t.end)}</span>);
    }
    pos = t.end;
  });
  if (pos < q.length) out.push(q.slice(pos));
  return out;
}

function FilterBar({
  value,
  onChange,
  bc,
  hasRepos,
  count,
  total,
}: {
  value: string;
  onChange: (v: string) => void;
  bc: BoardCtx;
  hasRepos: boolean;
  count: number;
  total: number;
}) {
  const reduce = useReducedMotion();
  const inputRef = useRef<HTMLInputElement>(null);
  const mirrorRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLSpanElement>(null);
  const wrapRef = useRef<HTMLDivElement>(null);
  const listId = useId();
  const [caret, setCaret] = useState(0);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const listRef = useRef<HTMLUListElement>(null);

  const tokens = useMemo(() => tokenize(value), [value]);
  const at = useMemo(() => contextAt(value, caret), [value, caret]);
  const items = useMemo(() => suggestionsFor(at, bc, hasRepos), [at, bc, hasRepos]);
  const show = open && items.length > 0;
  const act = Math.min(active, Math.max(0, items.length - 1));

  // "/" focuses the filter from anywhere on the board, as it does on GitHub.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = document.activeElement;
      const typing =
        el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement || (el as HTMLElement | null)?.isContentEditable;
      if (e.key === "/" && !typing && !e.metaKey && !e.ctrlKey) {
        e.preventDefault();
        inputRef.current?.focus();
        setOpen(true);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // Hang the list under the word being typed, the way GitHub does. Written
  // straight to the element: it is layout, not state.
  useLayoutEffect(() => {
    if (!show || !listRef.current) return;
    const w = wrapRef.current?.offsetWidth ?? 0;
    const x = 36 + (measureRef.current?.offsetWidth ?? 0) - (inputRef.current?.scrollLeft ?? 0);
    listRef.current.style.left = `${Math.max(0, Math.min(x - 8, w - 288))}px`;
  }, [show, value, at?.from]);

  const sync = () => {
    const el = inputRef.current;
    if (!el) return;
    setCaret(el.selectionStart ?? el.value.length);
    if (mirrorRef.current) mirrorRef.current.scrollLeft = el.scrollLeft;
  };

  const pick = (item: QItem) => {
    if (!at || item.disabled) return;
    const after = value.slice(at.to);
    const insert = item.insert + (item.kind === "value" && !/^[\s,]/.test(after) ? " " : "");
    const next = value.slice(0, at.from) + insert + after;
    const pos = at.from + insert.length;
    onChange(next);
    setActive(0);
    requestAnimationFrame(() => {
      const el = inputRef.current;
      if (!el) return;
      el.focus();
      el.setSelectionRange(pos, pos);
      setCaret(pos);
      if (mirrorRef.current) mirrorRef.current.scrollLeft = el.scrollLeft;
    });
  };

  const step = (dir: 1 | -1) => {
    if (!items.length) return;
    let i = act;
    for (let n = 0; n < items.length; n++) {
      i = (i + dir + items.length) % items.length;
      if (!items[i].disabled) break;
    }
    setActive(i);
    document.getElementById(`${listId}-${i}`)?.scrollIntoView({ block: "nearest" });
  };

  return (
    <div ref={wrapRef} className="relative min-w-0 flex-1">
      <div className="relative flex h-9 items-center rounded-md border border-stone-300 bg-white transition-[border-color,box-shadow] duration-150 focus-within:border-emerald-600 focus-within:ring-2 focus-within:ring-emerald-600/25 dark:border-stone-700 dark:bg-stone-950 dark:focus-within:border-emerald-400 dark:focus-within:ring-emerald-400/25">
        <Search aria-hidden className="pointer-events-none absolute left-3 h-4 w-4 text-stone-500" />
        <div
          ref={mirrorRef}
          aria-hidden
          className="pointer-events-none absolute inset-y-0 left-9 right-28 overflow-hidden whitespace-pre text-sm leading-[34px] text-stone-900 dark:text-stone-100"
        >
          {highlightQuery(value, tokens)}
        </div>
        <span ref={measureRef} aria-hidden className="invisible absolute left-0 top-0 whitespace-pre text-sm">
          {value.slice(0, at?.from ?? caret)}
        </span>
        <input
          ref={inputRef}
          role="combobox"
          aria-label="Filter cards"
          aria-expanded={show}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={show ? `${listId}-${act}` : undefined}
          value={value}
          spellCheck={false}
          autoComplete="off"
          placeholder="Filter by keyword or by field"
          onChange={(e) => {
            onChange(e.target.value);
            setOpen(true);
            setActive(0);
            requestAnimationFrame(sync);
          }}
          onFocus={() => {
            setOpen(true);
            sync();
          }}
          onBlur={() => setOpen(false)}
          onClick={() => {
            setOpen(true);
            sync();
          }}
          onKeyUp={(e) => {
            if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) {
              setActive(0);
              sync();
            }
          }}
          onScroll={sync}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") {
              e.preventDefault();
              if (!show) setOpen(true);
              else step(1);
            } else if (e.key === "ArrowUp" && show) {
              e.preventDefault();
              step(-1);
            } else if ((e.key === "Enter" || e.key === "Tab") && show && !items[act]?.disabled) {
              e.preventDefault();
              pick(items[act]);
            } else if (e.key === "Escape") {
              if (show) {
                e.stopPropagation();
                setOpen(false);
              } else inputRef.current?.blur();
            }
          }}
          className="h-full min-w-0 flex-1 bg-transparent pl-9 pr-28 text-sm text-transparent caret-stone-900 outline-none placeholder:text-stone-400 selection:bg-emerald-600/25 dark:caret-stone-100 dark:placeholder:text-stone-600"
        />
        <div className="absolute right-1.5 flex items-center gap-1">
          {value.trim() && (
            <span className="rounded-full bg-stone-100 px-2 text-[11px] leading-5 tabular-nums text-stone-600 dark:bg-stone-800 dark:text-stone-400">
              {count} of {total}
            </span>
          )}
          {value && (
            <button
              type="button"
              aria-label="Clear filter"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => {
                onChange("");
                setCaret(0);
                inputRef.current?.focus();
              }}
              className={cn(ICON_BTN, "h-6 w-6")}
            >
              <X aria-hidden className="h-3.5 w-3.5" />
            </button>
          )}
        </div>
      </div>

      <AnimatePresence>
        {show && (
          <motion.ul
            ref={listRef}
            id={listId}
            role="listbox"
            aria-label={at?.kind === "value" ? `${Q_FIELDS.find((f) => f.key === at.field)?.label} values` : "Filter fields"}
            initial={reduce ? { opacity: 0 } : { opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, transition: { duration: 0.1 } }}
            transition={{ duration: 0.15, ease: EASE_OUT }}
            style={{ transformOrigin: "top left" }}
            onMouseDown={(e) => e.preventDefault()}
            data-lenis-prevent
            className={cn(FLOATING, "absolute top-full z-40 mt-1.5 max-h-72 w-72 overflow-y-auto overscroll-contain p-1")}
          >
            {at?.kind === "value" && (
              <li role="presentation" className={cn(EYEBROW, "px-2 pb-1 pt-1.5")}>
                {Q_FIELDS.find((f) => f.key === at.field)?.label}
              </li>
            )}
            {items.map((it, i) => (
              <li
                key={`${it.kind}-${it.insert}-${i}`}
                id={`${listId}-${i}`}
                role="option"
                aria-selected={i === act}
                aria-disabled={it.disabled || undefined}
                onMouseEnter={() => !it.disabled && setActive(i)}
                onClick={() => pick(it)}
                className={cn(
                  "flex h-8 items-center gap-2 rounded-md px-2 text-sm",
                  it.disabled
                    ? "cursor-default text-stone-500"
                    : i === act
                    ? "cursor-pointer bg-stone-100 text-stone-900 dark:bg-stone-700 dark:text-stone-100"
                    : "cursor-pointer text-stone-700 dark:text-stone-200"
                )}
              >
                {it.adorn}
                <span className="min-w-0 flex-1 truncate">{it.label}</span>
                {it.hint && <span className="shrink-0 text-xs tabular-nums text-stone-500">{it.hint}</span>}
              </li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* View menu                                                                 */
/* ------------------------------------------------------------------------ */

const MENU_ROW =
  "flex h-9 w-full items-center gap-2 rounded-md px-2 text-left text-sm text-stone-700 transition-colors duration-150 hover:bg-stone-100 disabled:pointer-events-none disabled:opacity-50 dark:text-stone-200 dark:hover:bg-stone-700 " +
  FOCUS;

const LAYOUTS: { key: Layout; label: string; icon: LucideIcon }[] = [
  { key: "table", label: "Table", icon: Table2 },
  { key: "board", label: "Board", icon: SquareKanban },
  { key: "roadmap", label: "Roadmap", icon: ChartGantt },
];

function SortPanel({ sorts, onDone, hasRepos }: { sorts: SortRule[]; onDone: (s: SortRule[]) => void; hasRepos: boolean }) {
  // Picks stay a draft until Done, so the board deals once, for the final order, not on every click.
  const [draft, setDraft] = useState(sorts);
  return (
    <div className="flex flex-col">
      <p className="px-2 pb-2 text-xs text-stone-500">Select up to 2 fields</p>
      {SORT_FIELDS.filter((f) => f.field !== "repo" || hasRepos).map((f) => {
        const at = draft.findIndex((s) => s.field === f.field);
        const rule = draft[at];
        const Icon = f.icon;
        const DirIcon = rule?.dir === "asc" ? ArrowUpNarrowWide : ArrowDownWideNarrow;
        return (
          <div key={f.field} className="flex items-center gap-0.5">
            <button
              type="button"
              role="menuitemcheckbox"
              aria-checked={!!rule}
              data-menu-item
              className={MENU_ROW}
              onClick={() => {
                if (rule) setDraft(draft.filter((s) => s.field !== f.field));
                else setDraft([...(draft.length >= 2 ? draft.slice(0, 1) : draft), { field: f.field, dir: f.dir }]);
              }}
            >
              <span className="flex w-4 shrink-0 justify-center">
                {rule && <Check aria-hidden className="h-4 w-4 text-emerald-700 dark:text-emerald-400" />}
              </span>
              <Icon aria-hidden className="h-4 w-4 shrink-0 text-stone-500" />
              <span className="min-w-0 flex-1 truncate">{f.label}</span>
              {rule && draft.length > 1 && <span className="text-xs tabular-nums text-stone-500">{at + 1}</span>}
            </button>
            {rule && (
              <button
                type="button"
                data-menu-item
                aria-label={`${f.label}, ${rule.dir === "asc" ? "ascending" : "descending"}. Switch direction`}
                title={rule.dir === "asc" ? "Ascending" : "Descending"}
                onClick={() =>
                  setDraft(draft.map((s) => (s.field === f.field ? { ...s, dir: s.dir === "asc" ? "desc" : "asc" } : s)))
                }
                className={cn(ICON_BTN, "h-8 w-8")}
              >
                <DirIcon aria-hidden className="h-4 w-4" />
              </button>
            )}
          </div>
        );
      })}
      <div className="mt-1.5 flex justify-between gap-2 border-t border-stone-200 px-1 pt-2.5 pb-1 dark:border-stone-700">
        <button
          type="button"
          data-menu-item
          disabled={!draft.length}
          onClick={() => setDraft([])}
          className={cn(GHOST, "h-8 px-3 text-xs")}
        >
          No sorting
        </button>
        <button type="button" data-menu-item onClick={() => onDone(draft)} className={cn(PRIMARY, "h-8 px-3 text-xs")}>
          Done
        </button>
      </div>
    </div>
  );
}

type Panel = "main" | "fields" | "column" | "lanes" | "sort" | "sum";

function ViewMenu({
  config,
  setConfig,
  setSorts,
  dirty,
  onSave,
  onDiscard,
  hasRepos,
}: {
  config: ViewConfig;
  setConfig: (fn: (c: ViewConfig) => ViewConfig) => void;
  setSorts: (s: SortRule[]) => void;
  dirty: boolean;
  onSave: () => void;
  onDiscard: () => void;
  hasRepos: boolean;
}) {
  const reduce = useReducedMotion();
  const [open, setOpen] = useState(false);
  const [panel, setPanel] = useState<Panel>("main");
  const [dir, setDir] = useState(1);
  const ref = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const cameFrom = useRef<Panel>("main");

  const go = (p: Panel) => {
    cameFrom.current = panel === "main" ? p : "main";
    setDir(p === "main" ? -1 : 1);
    setPanel(p);
  };

  useEffect(() => {
    if (!open) return;
    const onDown = (e: PointerEvent) => {
      if (!ref.current?.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      e.stopPropagation();
      if (panel !== "main") go("main");
      else setOpen(false);
    };
    document.addEventListener("pointerdown", onDown);
    document.addEventListener("keydown", onKey, true);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      document.removeEventListener("keydown", onKey, true);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, panel]);

  // Focus follows the panel: the first row of a sub-panel, or the row that opened it on the way back.
  useEffect(() => {
    if (!open) return;
    const root = panelRef.current;
    if (!root) return;
    const target =
      panel === "main" && cameFrom.current !== "main"
        ? root.querySelector<HTMLElement>(`[data-panel-row="${cameFrom.current}"]`)
        : root.querySelector<HTMLElement>("[data-menu-item]:not([disabled])");
    target?.focus({ preventScroll: true });
  }, [open, panel]);

  const roving = (e: ReactKeyboardEvent) => {
    if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
    const rows = Array.from(panelRef.current?.querySelectorAll<HTMLElement>("[data-menu-item]:not([disabled])") ?? []);
    const i = rows.indexOf(document.activeElement as HTMLElement);
    e.preventDefault();
    rows[(i + (e.key === "ArrowDown" ? 1 : -1) + rows.length) % rows.length]?.focus();
  };

  const board = config.layout === "board";
  const lanesLabel = board ? "Swimlanes" : "Group by";
  const laneOptions = GROUP_OPTIONS.filter((o) => !board || o.key !== config.columnBy);
  const summary = {
    fields: FIELD_OPTIONS.filter((f) => config.fields.includes(f.key))
      .map((f) => f.label)
      .join(", "),
    column: GROUP_OPTIONS.find((o) => o.key === config.columnBy)!.label,
    lanes: config.lanes === "none" ? "none" : GROUP_OPTIONS.find((o) => o.key === config.lanes)!.label,
    sort: config.sorts.map((s) => `${sortLabel(s.field)} ${s.dir === "asc" ? "↑" : "↓"}`).join(", ") || "Manual",
    sum: config.sum === "count" ? "Count" : "Estimate",
  };

  const radio = (on: boolean, label: string, onClick: () => void, key: string) => (
    <button key={key} type="button" role="menuitemradio" aria-checked={on} data-menu-item className={MENU_ROW} onClick={onClick}>
      <span className="flex w-4 shrink-0 justify-center">
        {on && <Check aria-hidden className="h-4 w-4 text-emerald-700 dark:text-emerald-400" />}
      </span>
      {label}
    </button>
  );

  const row = (p: Panel, icon: LucideIcon, label: string, value: string) => {
    const Icon = icon;
    return (
      <button type="button" data-menu-item data-panel-row={p} className={MENU_ROW} onClick={() => go(p)}>
        <Icon aria-hidden className="h-4 w-4 shrink-0 text-stone-500" />
        <span className="shrink-0">{label}</span>
        <span className="min-w-0 flex-1 truncate text-right text-xs text-stone-500">{value}</span>
        <ChevronRight aria-hidden className="h-4 w-4 shrink-0 text-stone-400 dark:text-stone-500" />
      </button>
    );
  };

  const titles: Record<Panel, string> = {
    main: "View",
    fields: "Fields",
    column: "Column by",
    lanes: lanesLabel,
    sort: "Sort by",
    sum: "Field sum",
  };

  return (
    <div ref={ref} className="relative shrink-0">
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => {
          setPanel("main");
          cameFrom.current = "main";
          setOpen((o) => !o);
        }}
        className={cn(GHOST, "relative h-9 px-3")}
      >
        <Settings2 aria-hidden className="h-4 w-4" />
        View
        {dirty && (
          <span
            aria-label="Unsaved changes"
            className="absolute -right-1 -top-1 h-2.5 w-2.5 rounded-full bg-emerald-600 ring-2 ring-stone-50 dark:bg-emerald-400 dark:ring-stone-950"
          />
        )}
      </button>
      <AnimatePresence>
        {open && (
          <motion.div
            role="menu"
            aria-label="View options"
            initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.97, y: -4 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, transition: { duration: 0.12 } }}
            transition={{ duration: 0.18, ease: EASE_OUT }}
            style={{ transformOrigin: "top right" }}
            className={cn(FLOATING, "absolute right-0 top-full z-40 mt-1.5 w-80 overflow-hidden")}
          >
            <motion.div layout={!reduce} transition={{ duration: 0.18, ease: EASE_OUT }} className="overflow-hidden">
              <AnimatePresence mode="popLayout" initial={false} custom={dir}>
                <motion.div
                  key={panel}
                  ref={panelRef}
                  custom={dir}
                  initial={reduce ? { opacity: 0 } : { opacity: 0, x: dir * 24 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={reduce ? { opacity: 0 } : { opacity: 0, x: dir * -24, transition: { duration: 0.12 } }}
                  transition={{ duration: 0.18, ease: EASE_OUT }}
                  onKeyDown={roving}
                  className="p-1.5"
                >
                  {panel === "main" ? (
                    <>
                      <div
                        role="radiogroup"
                        aria-label="Layout"
                        className="grid grid-cols-3 gap-0.5 rounded-md bg-stone-100 p-0.5 dark:bg-stone-950"
                      >
                        {LAYOUTS.map((l) => {
                          const Icon = l.icon;
                          const on = config.layout === l.key;
                          return (
                            <button
                              key={l.key}
                              type="button"
                              role="radio"
                              aria-checked={on}
                              data-menu-item
                              onClick={() =>
                                setConfig((c) => ({
                                  ...c,
                                  layout: l.key,
                                  lanes: l.key === "board" && c.lanes === c.columnBy ? "none" : c.lanes,
                                }))
                              }
                              className={cn(
                                "inline-flex h-8 items-center justify-center gap-1.5 rounded text-xs font-medium transition-colors duration-150",
                                on
                                  ? "bg-white text-stone-900 shadow-[0_1px_2px_-1px_rgba(0,0,0,0.12)] dark:bg-stone-800 dark:text-stone-100"
                                  : "text-stone-600 hover:text-stone-900 dark:text-stone-400 dark:hover:text-stone-100",
                                FOCUS
                              )}
                            >
                              <Icon aria-hidden className="h-3.5 w-3.5" />
                              {l.label}
                            </button>
                          );
                        })}
                      </div>
                      <div className="mt-1.5 flex flex-col">
                        {row("fields", Rows3, "Fields", summary.fields)}
                        {board && row("column", Columns3, "Column by", summary.column)}
                        {row("lanes", Rows2, lanesLabel, summary.lanes)}
                        {row("sort", ArrowUpDown, "Sort by", summary.sort)}
                        {board && row("sum", Hash, "Field sum", summary.sum)}
                      </div>
                      <div className="mt-1.5 flex justify-end gap-2 border-t border-stone-200 px-1 pt-2.5 pb-1 dark:border-stone-700">
                        <button
                          type="button"
                          data-menu-item
                          disabled={!dirty}
                          onClick={onDiscard}
                          className={cn(GHOST, "h-8 px-3 text-xs")}
                        >
                          Discard
                        </button>
                        <button
                          type="button"
                          data-menu-item
                          disabled={!dirty}
                          onClick={() => {
                            onSave();
                            setOpen(false);
                          }}
                          className={cn(PRIMARY, "h-8 px-3 text-xs")}
                        >
                          Save view
                        </button>
                      </div>
                    </>
                  ) : (
                    <>
                      <div className="mb-1 flex items-center gap-1">
                        <button
                          type="button"
                          aria-label="Back"
                          data-menu-item
                          onClick={() => go("main")}
                          className={cn(ICON_BTN, "h-7 w-7")}
                        >
                          <ChevronLeft aria-hidden className="h-4 w-4" />
                        </button>
                        <span className="text-sm font-medium text-stone-900 dark:text-stone-100">{titles[panel]}</span>
                      </div>
                      {panel === "fields" &&
                        FIELD_OPTIONS.map((f) => {
                          const on = config.fields.includes(f.key);
                          return (
                            <button
                              key={f.key}
                              type="button"
                              role="menuitemcheckbox"
                              aria-checked={on}
                              data-menu-item
                              className={MENU_ROW}
                              onClick={() =>
                                setConfig((c) => ({
                                  ...c,
                                  fields: on
                                    ? c.fields.filter((x) => x !== f.key)
                                    : FIELD_OPTIONS.map((o) => o.key).filter((k) => k === f.key || c.fields.includes(k)),
                                }))
                              }
                            >
                              <span
                                aria-hidden
                                className={cn(
                                  "flex h-4 w-4 shrink-0 items-center justify-center rounded border",
                                  on ? "border-emerald-700 bg-emerald-700 text-white" : "border-stone-300 dark:border-stone-600"
                                )}
                              >
                                {on && <Check className="h-3 w-3" strokeWidth={3} />}
                              </span>
                              {f.label}
                            </button>
                          );
                        })}
                      {panel === "column" &&
                        GROUP_OPTIONS.map((o) =>
                          radio(
                            config.columnBy === o.key,
                            o.label,
                            () => setConfig((c) => ({ ...c, columnBy: o.key, lanes: c.lanes === o.key ? "none" : c.lanes })),
                            o.key
                          )
                        )}
                      {panel === "lanes" && (
                        <>
                          {radio(config.lanes === "none", "None", () => setConfig((c) => ({ ...c, lanes: "none" })), "none")}
                          {laneOptions.map((o) =>
                            radio(config.lanes === o.key, o.label, () => setConfig((c) => ({ ...c, lanes: o.key })), o.key)
                          )}
                        </>
                      )}
                      {panel === "sort" && (
                        <SortPanel
                          sorts={config.sorts}
                          hasRepos={hasRepos}
                          onDone={(next) => {
                            setOpen(false);
                            triggerRef.current?.focus({ preventScroll: true });
                            if (JSON.stringify(next) !== JSON.stringify(config.sorts)) setSorts(next);
                          }}
                        />
                      )}
                      {panel === "sum" && (
                        <>
                          {radio(config.sum === "count", "Count", () => setConfig((c) => ({ ...c, sum: "count" })), "count")}
                          {radio(
                            config.sum === "estimate",
                            "Estimate",
                            () => setConfig((c) => ({ ...c, sum: "estimate" })),
                            "estimate"
                          )}
                        </>
                      )}
                    </>
                  )}
                </motion.div>
              </AnimatePresence>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* View tabs                                                                 */
/* ------------------------------------------------------------------------ */

const layoutIcon = (l: Layout) => LAYOUTS.find((x) => x.key === l)!.icon;

function ViewTabs({
  views,
  activeId,
  dirty,
  configOf,
  onSelect,
  onNew,
  onRename,
  onDuplicate,
  onDelete,
}: {
  views: SavedView[];
  activeId: string;
  dirty: Set<string>;
  configOf: (v: SavedView) => ViewConfig;
  onSelect: (id: string) => void;
  onNew: () => string;
  onRename: (id: string, name: string) => void;
  onDuplicate: (id: string) => void;
  onDelete: (id: string) => void;
}) {
  const reduce = useReducedMotion();
  const [renaming, setRenaming] = useState<string | null>(null);
  const [menu, setMenu] = useState<{ id: string; left: number } | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const closeMenu = useCallback(() => setMenu(null), []);
  useDismiss(!!menu, menuRef, closeMenu);

  const onKeys = (e: ReactKeyboardEvent) => {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    const tabs = Array.from(rootRef.current?.querySelectorAll<HTMLElement>('[role="tab"]') ?? []);
    const i = tabs.indexOf(document.activeElement as HTMLElement);
    if (i < 0) return;
    e.preventDefault();
    tabs[(i + (e.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length]?.focus();
  };

  const item =
    "flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-xs text-stone-700 transition-colors duration-150 hover:bg-stone-100 disabled:pointer-events-none disabled:opacity-50 dark:text-stone-200 dark:hover:bg-stone-700 " +
    FOCUS;

  return (
    <div ref={rootRef} className="relative flex shrink-0 items-end gap-1 border-b border-stone-200 px-5 dark:border-stone-800">
      <div
        role="tablist"
        aria-label="Views"
        onKeyDown={onKeys}
        className="scrollbar-hide flex min-w-0 items-end overflow-x-auto"
        data-lenis-prevent
      >
        {views.map((v) => {
          const on = v.id === activeId;
          const Icon = layoutIcon(configOf(v).layout);
          return (
            <div key={v.id} className="relative flex shrink-0 items-center">
              {renaming === v.id ? (
                <input
                  autoFocus
                  defaultValue={v.name}
                  aria-label="View name"
                  maxLength={32}
                  onFocus={(e) => e.currentTarget.select()}
                  onBlur={(e) => {
                    const n = e.target.value.trim();
                    if (n) onRename(v.id, n);
                    setRenaming(null);
                  }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") (e.target as HTMLInputElement).blur();
                    if (e.key === "Escape") setRenaming(null);
                  }}
                  className={cn(INPUT, "my-1.5 h-7 w-40 px-2 text-xs")}
                />
              ) : (
                <button
                  type="button"
                  role="tab"
                  aria-selected={on}
                  tabIndex={on ? 0 : -1}
                  onClick={() => onSelect(v.id)}
                  onDoubleClick={() => setRenaming(v.id)}
                  className={cn(
                    "relative inline-flex h-10 items-center gap-1.5 px-3 text-sm transition-colors duration-150",
                    on
                      ? "font-medium text-stone-900 dark:text-stone-100"
                      : "text-stone-500 hover:text-stone-900 dark:hover:text-stone-100",
                    FOCUS
                  )}
                >
                  <Icon aria-hidden className="h-4 w-4 shrink-0" />
                  <span className="whitespace-nowrap">{v.name}</span>
                  {dirty.has(v.id) && (
                    <span aria-label="unsaved" className="h-1.5 w-1.5 rounded-full bg-emerald-600 dark:bg-emerald-400" />
                  )}
                  {on && (
                    <motion.span
                      layoutId="deck-view-tab"
                      transition={reduce ? { duration: 0 } : { type: "spring", duration: 0.3, bounce: 0.1 }}
                      className="absolute inset-x-2 -bottom-px h-0.5 rounded-full bg-emerald-700 dark:bg-emerald-400"
                    />
                  )}
                </button>
              )}
              {on && renaming !== v.id && (
                <button
                  type="button"
                  aria-label={`${v.name} options`}
                  aria-haspopup="menu"
                  aria-expanded={menu?.id === v.id}
                  onClick={(e) => {
                    const r = e.currentTarget.getBoundingClientRect();
                    const rr = rootRef.current!.getBoundingClientRect();
                    setMenu((m) => (m ? null : { id: v.id, left: Math.min(r.left - rr.left, rr.width - 184) }));
                  }}
                  className={cn(ICON_BTN, "-ml-1 h-6 w-6")}
                >
                  <ChevronDown aria-hidden className="h-3.5 w-3.5" />
                </button>
              )}
              <span aria-hidden className="mx-1 h-4 w-px bg-stone-200 dark:bg-stone-800" />
            </div>
          );
        })}
      </div>
      <button
        type="button"
        onClick={() => setRenaming(onNew())}
        className={cn(
          "inline-flex h-10 shrink-0 items-center gap-1.5 px-2 text-sm text-stone-500 transition-colors duration-150 hover:text-stone-900 dark:hover:text-stone-100",
          FOCUS
        )}
      >
        <Plus aria-hidden className="h-4 w-4" /> New view
      </button>

      <AnimatePresence>
        {menu && (
          <motion.div
            ref={menuRef}
            role="menu"
            initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.97, y: -2 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, transition: { duration: 0.1 } }}
            transition={{ duration: 0.16, ease: EASE_OUT }}
            style={{ left: menu.left, transformOrigin: "top left" }}
            className={cn(FLOATING, "absolute top-full z-40 mt-1 w-44 p-1")}
          >
            <button
              type="button"
              role="menuitem"
              className={item}
              onClick={() => {
                setRenaming(menu.id);
                setMenu(null);
              }}
            >
              <Pencil aria-hidden className="h-3.5 w-3.5" /> Rename view
            </button>
            <button
              type="button"
              role="menuitem"
              className={item}
              onClick={() => {
                onDuplicate(menu.id);
                setMenu(null);
              }}
            >
              <Copy aria-hidden className="h-3.5 w-3.5" /> Duplicate view
            </button>
            <button
              type="button"
              role="menuitem"
              disabled={views.length < 2}
              className={cn(item, "text-red-700 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-950/40")}
              onClick={() => {
                onDelete(menu.id);
                setMenu(null);
              }}
            >
              <Trash2 aria-hidden className="h-3.5 w-3.5" /> Delete view
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Table layout                                                              */
/* ------------------------------------------------------------------------ */

const TABLE_COLS: { key: FieldKey | "title" | "status"; label: string; sort?: SortField; width: string }[] = [
  { key: "title", label: "Title", sort: "title", width: "min-w-[320px]" },
  { key: "status", label: "Status", sort: "status", width: "w-36" },
  { key: "assignee", label: "Assignee", sort: "assignee", width: "w-40" },
  { key: "labels", label: "Labels", sort: "labels", width: "w-48" },
  { key: "priority", label: "Priority", sort: "priority", width: "w-32" },
  { key: "due", label: "Due", sort: "due", width: "w-24" },
  { key: "progress", label: "Progress", sort: "progress", width: "w-40" },
  { key: "estimate", label: "Estimate", sort: "estimate", width: "w-24" },
  { key: "parent", label: "Parent", width: "w-48" },
];

function TableView({
  rows,
  lanes,
  bc,
  config,
  onSortColumn,
  onOpen,
  onAdd,
}: {
  rows: Card[];
  lanes: Group[];
  bc: BoardCtx;
  config: ViewConfig;
  onSortColumn: (f: SortField) => void;
  onOpen: (id: string) => void;
  onAdd: (title: string, lane: Group) => void;
}) {
  const reduce = useReducedMotion();
  const [adding, setAdding] = useState<string | null>(null);
  const cols = TABLE_COLS.filter((c) => c.key === "title" || c.key === "status" || config.fields.includes(c.key as FieldKey));
  const byId = useMemo(() => new Map(bc.board.cards.map((c) => [c.id, c])), [bc.board.cards]);

  const cell = (c: Card, key: (typeof TABLE_COLS)[number]["key"]): ReactNode => {
    switch (key) {
      case "title":
        return (
          <span className="flex min-w-0 items-center gap-2">
            {config.fields.includes("key") && (
              <span className="shrink-0 font-[family-name:var(--font-deck-mono)] text-[11px] text-stone-500">{c.key}</span>
            )}
            <span className="truncate font-medium text-stone-900 dark:text-stone-100">{c.title}</span>
          </span>
        );
      case "status": {
        const col = bc.board.columns.find((x) => x.id === c.columnId);
        return col ? (
          <span className="inline-flex items-center gap-1.5">
            <Dot color={col.color} /> {col.name}
          </span>
        ) : null;
      }
      case "assignee": {
        const p = c.assigneeId ? bc.people.get(c.assigneeId) : undefined;
        return p ? (
          <span className="inline-flex min-w-0 items-center gap-1.5">
            <Initials person={p} size="xs" />
            <span className="truncate">{p.name}</span>
          </span>
        ) : (
          <span className="text-stone-400 dark:text-stone-600">Unassigned</span>
        );
      }
      case "labels":
        return (
          <span className="flex min-w-0 gap-1 overflow-hidden">
            {c.labelIds.slice(0, 2).map((id) => {
              const l = bc.labels.get(id);
              return l ? (
                <LabelChip key={id} color={l.color} size="sm">
                  {l.name}
                </LabelChip>
              ) : null;
            })}
            {c.labelIds.length > 2 && <span className="text-[11px] text-stone-500">+{c.labelIds.length - 2}</span>}
          </span>
        );
      case "priority":
        return (
          <span className="inline-flex items-center gap-1.5">
            <PriorityGlyph priority={c.priority} /> {PRIORITIES[c.priority]}
          </span>
        );
      case "due": {
        const s = dueState(c.due, c.columnId);
        return c.due ? (
          <span
            className={cn(
              "tabular-nums",
              s === "overdue" && "text-red-700 dark:text-red-400",
              s === "soon" && "text-amber-700 dark:text-amber-400"
            )}
          >
            {shortDate(c.due)}
          </span>
        ) : null;
      }
      case "progress":
        return <ProgressMeter p={cardProgress(c, bc)} />;
      case "estimate":
        return c.estimate !== null ? <span className="tabular-nums">{c.estimate}</span> : null;
      case "parent": {
        const p = c.parentId ? byId.get(c.parentId) : undefined;
        return p ? (
          <span className="flex min-w-0 items-center gap-1 text-stone-600 dark:text-stone-400">
            <CornerDownRight aria-hidden className="h-3.5 w-3.5 shrink-0" />
            <span className="truncate">{p.title}</span>
          </span>
        ) : null;
      }
    }
  };

  const groups = lanes.map((l) => ({ lane: l, cards: rows.filter(l.match) })).filter((g) => g.cards.length || lanes.length === 1);

  return (
    <div className="flex-1 overflow-x-auto overscroll-x-contain px-5 pb-5" data-lenis-prevent>
      <table className="w-full min-w-[960px] border-separate border-spacing-0 text-sm">
        <thead>
          <tr>
            {cols.map((c) => {
              const at = c.sort ? config.sorts.findIndex((s) => s.field === c.sort) : -1;
              const rule = config.sorts[at];
              return (
                <th
                  key={c.key}
                  scope="col"
                  aria-sort={at === 0 ? (rule.dir === "asc" ? "ascending" : "descending") : undefined}
                  className={cn(
                    "sticky top-0 z-10 border-b border-stone-200 bg-stone-50 px-3 py-2 text-left text-xs font-medium text-stone-600 dark:border-stone-800 dark:bg-stone-950 dark:text-stone-400",
                    c.width
                  )}
                >
                  {c.sort ? (
                    <button
                      type="button"
                      onClick={() => onSortColumn(c.sort!)}
                      className={cn(
                        "inline-flex items-center gap-1 rounded hover:text-stone-900 dark:hover:text-stone-100",
                        FOCUS
                      )}
                    >
                      {c.label}
                      {rule &&
                        (rule.dir === "asc" ? (
                          <ArrowUpNarrowWide aria-hidden className="h-3.5 w-3.5" />
                        ) : (
                          <ArrowDownWideNarrow aria-hidden className="h-3.5 w-3.5" />
                        ))}
                    </button>
                  ) : (
                    c.label
                  )}
                </th>
              );
            })}
          </tr>
        </thead>
        {groups.map(({ lane, cards }) => (
          <tbody key={lane.id}>
            {lanes.length > 1 && (
              <tr>
                <th
                  colSpan={cols.length}
                  scope="rowgroup"
                  className="border-b border-stone-200 bg-stone-100/70 px-3 py-2 text-left text-xs font-semibold text-stone-700 dark:border-stone-800 dark:bg-stone-900/60 dark:text-stone-300"
                >
                  <span className="inline-flex items-center gap-2">
                    {lane.column && <Dot color={lane.column.color} />}
                    {lane.priority !== undefined && <PriorityGlyph priority={lane.priority} />}
                    {lane.person && <Initials person={lane.person} size="xs" />}
                    {lane.name}
                    <span className="font-normal tabular-nums text-stone-500">{cards.length}</span>
                  </span>
                </th>
              </tr>
            )}
            {cards.map((c) => (
              <motion.tr
                key={c.id}
                layout={reduce ? false : "position"}
                transition={{ duration: 0.2, ease: EASE_OUT }}
                tabIndex={0}
                onClick={() => onOpen(c.id)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") onOpen(c.id);
                  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
                    e.preventDefault();
                    const tr = e.currentTarget;
                    const next = (
                      e.key === "ArrowDown" ? tr.nextElementSibling : tr.previousElementSibling
                    ) as HTMLElement | null;
                    if (next?.tabIndex === 0) next.focus();
                  }
                }}
                className="group cursor-pointer outline-none transition-colors duration-150 hover:bg-white focus-visible:bg-white focus-visible:outline focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-stone-900 dark:focus-visible:bg-stone-900 dark:focus-visible:outline-emerald-400"
              >
                {cols.map((col) => (
                  <td
                    key={col.key}
                    className={cn(
                      "h-10 max-w-0 whitespace-nowrap border-b border-stone-200/80 px-3 text-stone-700 dark:border-stone-800/80 dark:text-stone-300",
                      col.width
                    )}
                  >
                    {cell(c, col.key)}
                  </td>
                ))}
              </motion.tr>
            ))}
            <tr>
              <td colSpan={cols.length} className="border-b border-stone-200/80 px-1.5 py-1 dark:border-stone-800/80">
                {adding === lane.id ? (
                  <form
                    onSubmit={(e) => {
                      e.preventDefault();
                      const input = e.currentTarget.elements.namedItem("title") as HTMLInputElement;
                      const t = input.value.trim();
                      if (t) onAdd(t, lane);
                      input.value = "";
                    }}
                  >
                    <input
                      name="title"
                      autoFocus
                      placeholder="Title, then Enter"
                      aria-label="New item title"
                      onBlur={() => setAdding(null)}
                      onKeyDown={(e) => e.key === "Escape" && setAdding(null)}
                      className={cn(INPUT, "h-8 w-full max-w-md text-xs")}
                    />
                  </form>
                ) : (
                  <button
                    type="button"
                    onClick={() => setAdding(lane.id)}
                    className={cn(
                      "inline-flex h-8 items-center gap-1.5 rounded-md px-2 text-xs text-stone-500 hover:bg-stone-100 hover:text-stone-900 dark:hover:bg-stone-800 dark:hover:text-stone-100",
                      FOCUS
                    )}
                  >
                    <Plus aria-hidden className="h-3.5 w-3.5" /> Add item
                  </button>
                )}
              </td>
            </tr>
          </tbody>
        ))}
      </table>
      {rows.length === 0 && <p className="py-10 text-center text-sm text-stone-500">Nothing matches this filter.</p>}
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Roadmap layout                                                            */
/*                                                                           */
/* One row per card, a bar from its start date to its due date, drawn over   */
/* a day grid with the weekend shaded and a line at today. Drag a bar to    */
/* move it, drag either end to change that date; both snap to whole days.  */
/* ------------------------------------------------------------------------ */

const DAY_MS = 86_400_000;
const isoOfDay = (n: number) => {
  const d = new Date(n * DAY_MS);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
};

type Zoom = "week" | "month";

function RoadmapView({
  rows,
  lanes,
  bc,
  onOpen,
  onDates,
}: {
  rows: Card[];
  lanes: Group[];
  bc: BoardCtx;
  onOpen: (id: string) => void;
  onDates: (id: string, start: string | null, due: string | null) => void;
}) {
  const reduce = useReducedMotion();
  const [zoom, setZoom] = useState<Zoom>("week");
  const [edit, setEdit] = useState<{ id: string; start: number; end: number } | null>(null);
  const moved = useRef(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const dayW = zoom === "week" ? 40 : 16;
  const today = dayNumber(TODAY);

  const dated = rows.filter((c) => c.start || c.due);
  const days = dated.flatMap((c) => [c.start, c.due].filter(Boolean).map((d) => dayNumber(d!)));
  const first = Math.min(today - 7, ...days) - 2;
  const last = Math.max(today + 14, ...days) + 4;
  const span = last - first + 1;
  const x = (d: number) => (d - first) * dayW;

  // Open on today, with a couple of days of context before it, the way GitHub's roadmap does.
  useEffect(() => {
    const sc = scrollRef.current;
    if (sc) sc.scrollLeft = Math.max(0, (today - first - 2) * dayW);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [zoom]);

  const beginDrag = (e: ReactPointerEvent, c: Card, mode: "move" | "start" | "end") => {
    if (e.button !== 0) return;
    e.stopPropagation();
    e.preventDefault();
    const s0 = c.start ? dayNumber(c.start) : dayNumber(c.due!);
    const e0 = c.due ? dayNumber(c.due) : s0;
    const x0 = e.clientX;
    moved.current = false;
    setEdit({ id: c.id, start: s0, end: e0 });
    const move = (ev: PointerEvent) => {
      const d = Math.round((ev.clientX - x0) / dayW);
      if (d) moved.current = true;
      if (mode === "move") setEdit({ id: c.id, start: s0 + d, end: e0 + d });
      else if (mode === "start") setEdit({ id: c.id, start: Math.min(s0 + d, e0), end: e0 });
      else setEdit({ id: c.id, start: s0, end: Math.max(e0 + d, s0) });
    };
    const up = (ev: PointerEvent) => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      const d = Math.round((ev.clientX - x0) / dayW);
      let s = s0;
      let en = e0;
      if (mode === "move") {
        s += d;
        en += d;
      } else if (mode === "start") s = Math.min(s0 + d, e0);
      else en = Math.max(e0 + d, s0);
      setEdit(null);
      if (d) onDates(c.id, isoOfDay(s), isoOfDay(en));
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };

  const onBarKey = (e: ReactKeyboardEvent, c: Card) => {
    if (e.key === "Enter") return onOpen(c.id);
    if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
    e.preventDefault();
    const d = e.key === "ArrowRight" ? 1 : -1;
    const s = c.start ? dayNumber(c.start) : dayNumber(c.due!);
    const en = c.due ? dayNumber(c.due) : s;
    // Shift+arrow changes the end date only; plain arrows move the whole bar.
    if (e.shiftKey) onDates(c.id, isoOfDay(s), isoOfDay(Math.max(s, en + d)));
    else onDates(c.id, isoOfDay(s + d), isoOfDay(en + d));
  };

  const groups = lanes.map((l) => ({ lane: l, cards: rows.filter(l.match) })).filter((g) => g.cards.length || lanes.length === 1);

  return (
    <div className="flex flex-1 flex-col px-5 pb-5">
      <div className="mb-2 flex items-center gap-2">
        <div
          role="radiogroup"
          aria-label="Zoom"
          className="inline-grid grid-cols-2 gap-0.5 rounded-md bg-stone-200/60 p-0.5 dark:bg-stone-900"
        >
          {(["week", "month"] as Zoom[]).map((z) => (
            <button
              key={z}
              type="button"
              role="radio"
              aria-checked={zoom === z}
              onClick={() => setZoom(z)}
              className={cn(
                "h-7 rounded px-3 text-xs font-medium capitalize transition-colors duration-150",
                zoom === z
                  ? "bg-white text-stone-900 shadow-[0_1px_2px_-1px_rgba(0,0,0,0.12)] dark:bg-stone-800 dark:text-stone-100"
                  : "text-stone-600 hover:text-stone-900 dark:text-stone-400 dark:hover:text-stone-100",
                FOCUS
              )}
            >
              {z}
            </button>
          ))}
        </div>
        <span className="text-xs text-stone-500">Drag a bar to move it, or an end to change that date. Arrow keys work too.</span>
      </div>
      <div
        ref={scrollRef}
        className="overflow-x-auto overscroll-x-contain rounded-xl border border-stone-200 bg-white dark:border-stone-800 dark:bg-stone-900"
        data-lenis-prevent
      >
        <div className="relative" style={{ width: 288 + span * dayW }}>
          {/* Header: months over days */}
          <div className="sticky top-0 z-20 flex border-b border-stone-200 bg-white dark:border-stone-800 dark:bg-stone-900">
            <div className="sticky left-0 z-10 w-72 shrink-0 border-r border-stone-200 bg-white px-3 py-2 text-xs font-medium text-stone-600 dark:border-stone-800 dark:bg-stone-900 dark:text-stone-400">
              Title
            </div>
            <div className="relative h-12" style={{ width: span * dayW }}>
              {Array.from({ length: span }, (_, i) => {
                const iso = isoOfDay(first + i);
                const d = new Date((first + i) * DAY_MS);
                const dow = d.getUTCDay();
                const dom = d.getUTCDate();
                const showNum = zoom === "week" || dow === 1;
                return (
                  <div key={iso} className="absolute top-0 h-full" style={{ left: i * dayW, width: dayW }}>
                    {(dom === 1 || i === 0) && (
                      <span className="absolute left-1 top-1 whitespace-nowrap text-[11px] font-medium text-stone-700 dark:text-stone-300">
                        {MONTHS[d.getUTCMonth()]}
                      </span>
                    )}
                    {showNum && (
                      <span
                        className={cn(
                          "absolute bottom-1 left-0 w-full text-center text-[11px] tabular-nums",
                          first + i === today ? "font-semibold text-emerald-700 dark:text-emerald-400" : "text-stone-500"
                        )}
                      >
                        {dom}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Grid: weekends and today */}
          <div aria-hidden className="pointer-events-none absolute bottom-0 left-72 top-12" style={{ width: span * dayW }}>
            {Array.from({ length: span }, (_, i) => {
              const dow = new Date((first + i) * DAY_MS).getUTCDay();
              return dow === 0 || dow === 6 ? (
                <div
                  key={i}
                  className="absolute inset-y-0 bg-stone-100/70 dark:bg-stone-950/40"
                  style={{ left: i * dayW, width: dayW }}
                />
              ) : null;
            })}
            <div
              className="absolute inset-y-0 w-0.5 bg-emerald-600 dark:bg-emerald-400"
              style={{ left: x(today) + dayW / 2 - 1 }}
            />
          </div>

          {groups.map(({ lane, cards }) => (
            <div key={lane.id} role="group" aria-label={lanes.length > 1 ? lane.name : "Roadmap"}>
              {lanes.length > 1 && (
                <div className="sticky left-0 flex h-8 w-72 items-center gap-2 border-b border-r border-stone-200 bg-stone-50 px-3 text-xs font-semibold text-stone-700 dark:border-stone-800 dark:bg-stone-950 dark:text-stone-300">
                  {lane.column && <Dot color={lane.column.color} />}
                  {lane.priority !== undefined && <PriorityGlyph priority={lane.priority} />}
                  {lane.person && <Initials person={lane.person} size="xs" />}
                  {lane.name}
                  <span className="font-normal tabular-nums text-stone-500">{cards.length}</span>
                </div>
              )}
              {cards.map((c) => {
                const col = bc.board.columns.find((k) => k.id === c.columnId);
                const color = col?.color ?? "#a8a29e";
                const live = edit?.id === c.id ? edit : null;
                const hasDates = !!(c.start || c.due);
                const s = live ? live.start : c.start ? dayNumber(c.start) : c.due ? dayNumber(c.due) : 0;
                const en = live ? live.end : c.due ? dayNumber(c.due) : s;
                const p = cardProgress(c, bc);
                return (
                  <div key={c.id} className="group/row flex h-10 border-b border-stone-100 dark:border-stone-800/60">
                    <button
                      type="button"
                      onClick={() => onOpen(c.id)}
                      className={cn(
                        "sticky left-0 z-10 flex w-72 shrink-0 items-center gap-2 border-r border-stone-200 bg-white px-3 text-left text-sm hover:bg-stone-50 dark:border-stone-800 dark:bg-stone-900 dark:hover:bg-stone-800",
                        FOCUS
                      )}
                    >
                      <Dot color={color} />
                      <span className="shrink-0 font-[family-name:var(--font-deck-mono)] text-[11px] text-stone-500">
                        {c.key}
                      </span>
                      <span className="truncate text-stone-900 dark:text-stone-100">{c.title}</span>
                    </button>
                    <div className="relative" style={{ width: span * dayW }}>
                      {hasDates ? (
                        <div
                          role="button"
                          tabIndex={0}
                          aria-label={`${c.key} ${c.title}, ${c.start ? shortDate(isoOfDay(s)) + " to " : "due "}${shortDate(
                            isoOfDay(en)
                          )}`}
                          onPointerDown={(e) => beginDrag(e, c, "move")}
                          onClick={() => {
                            if (!moved.current) onOpen(c.id);
                          }}
                          onKeyDown={(e) => onBarKey(e, c)}
                          style={{ ...cardVars(color), left: x(s) + 2, width: Math.max(dayW - 4, (en - s + 1) * dayW - 4) }}
                          className={cn(
                            "absolute top-1.5 flex h-7 cursor-grab touch-none select-none items-center overflow-hidden rounded-md border bg-[var(--card-bg)] border-[color:var(--card-line)] text-xs text-stone-800 dark:bg-[var(--card-bg-dark)] dark:border-[color:var(--card-line-dark)] dark:text-stone-200",
                            live ? "shadow-[0_6px_16px_-8px_rgba(28,25,23,0.35)]" : "transition-[left,width] duration-150",
                            reduce && "transition-none",
                            FOCUS
                          )}
                        >
                          <span
                            aria-hidden
                            className="absolute inset-y-0 left-0 opacity-25"
                            style={{ width: `${p.value * 100}%`, background: color }}
                          />
                          <span
                            aria-hidden
                            onPointerDown={(e) => beginDrag(e, c, "start")}
                            className="absolute inset-y-0 left-0 w-2 cursor-ew-resize hover:bg-black/10 dark:hover:bg-white/10"
                          />
                          <span className="relative truncate px-2.5">{c.title}</span>
                          <span
                            aria-hidden
                            onPointerDown={(e) => beginDrag(e, c, "end")}
                            className="absolute inset-y-0 right-0 w-2 cursor-ew-resize hover:bg-black/10 dark:hover:bg-white/10"
                          />
                        </div>
                      ) : (
                        <button
                          type="button"
                          onClick={() => onDates(c.id, TODAY, isoOfDay(today + 3))}
                          className={cn(
                            "absolute top-2 h-6 rounded-md border border-dashed border-stone-300 px-2 text-[11px] text-stone-500 opacity-0 transition-opacity duration-150 group-hover/row:opacity-100 focus-visible:opacity-100 dark:border-stone-700",
                            FOCUS
                          )}
                          style={{ left: x(today) + 4 }}
                        >
                          Add dates
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Insights                                                                  */
/*                                                                           */
/* GitHub's Insights, over whatever the current view's filter shows: a      */
/* burn-up across the sprint, work by status and by person, and the label  */
/* mix. The charts are the library's own.                                   */
/* ------------------------------------------------------------------------ */

function InsightsView({ cards, bc }: { cards: Card[]; bc: BoardCtx }) {
  const d0 = dayNumber(SPRINT_START);
  const d1 = dayNumber(SPRINT_END);
  const today = dayNumber(TODAY);
  const pts = (c: Card) => c.estimate ?? 1;

  const burn: ChartPoint[] = Array.from({ length: d1 - d0 + 1 }, (_, i) => {
    const d = d0 + i;
    const past = d <= today;
    const scope = cards.filter((c) => dayNumber(c.createdAt) <= d).reduce((s, c) => s + pts(c), 0);
    const done = cards.filter((c) => c.closedAt && dayNumber(c.closedAt) <= d).reduce((s, c) => s + pts(c), 0);
    const total = cards.reduce((s, c) => s + pts(c), 0);
    return {
      x: shortDate(isoOfDay(d)),
      values: {
        scope: past ? scope : null,
        done: past ? done : null,
        ideal: Math.round((total * i) / (d1 - d0)),
      },
    };
  });
  const burnSeries: SeriesSpec[] = [
    { id: "scope", label: "Scope, points" },
    { id: "done", label: "Completed, points" },
    // A reference, not data: stone-500 keeps it quiet and still clears 3:1 on white.
    { id: "ideal", label: "Even pace", color: "#78716c" },
  ];

  const statusPoints: ChartPoint[] = bc.board.columns.map((col) => ({
    x: col.name,
    values: { cards: cards.filter((c) => c.columnId === col.id).length },
  }));

  const people = [...bc.board.people.filter((p) => cards.some((c) => c.assigneeId === p.id))];
  const personSeries: SeriesSpec[] = bc.board.columns.map((col) => ({ id: col.id, label: col.name, color: col.color }));
  const personPoints: ChartPoint[] = [
    ...people.map((p) => ({ id: p.id as string | null, name: p.name })),
    { id: null, name: "Unassigned" },
  ].map((p) => ({
    x: p.name,
    values: Object.fromEntries(
      bc.board.columns.map((col) => [
        col.id,
        cards.filter((c) => c.assigneeId === p.id && c.columnId === col.id).reduce((s, c) => s + pts(c), 0),
      ])
    ),
  }));

  const labelSlices: PieSlice[] = bc.board.labels
    .map((l) => ({ id: l.id, label: l.name, value: cards.filter((c) => c.labelIds.includes(l.id)).length, color: l.color }))
    .filter((s) => s.value > 0);

  const open = cards.filter((c) => c.columnId !== DONE_ID);
  const tiles = [
    { label: "Open", value: open.length },
    { label: "Done", value: cards.length - open.length },
    { label: "Overdue", value: cards.filter((c) => dueState(c.due, c.columnId) === "overdue").length },
    { label: "Points left", value: open.reduce((s, c) => s + pts(c), 0) },
  ];

  const panel = "rounded-xl border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900";
  return (
    <div className="flex-1 px-5 pb-5">
      <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
        {tiles.map((t) => (
          <div key={t.label} className={panel}>
            <span className={EYEBROW}>{t.label}</span>
            <p className="mt-1 text-[28px] font-semibold leading-none tracking-tight tabular-nums text-stone-900 dark:text-stone-100">
              {t.value}
            </p>
          </div>
        ))}
      </div>
      <div className="mt-3 grid gap-3 lg:grid-cols-3">
        <section className={cn(panel, "lg:col-span-2")} aria-labelledby="deck-burnup">
          <h3 id="deck-burnup" className="text-sm font-medium text-stone-900 dark:text-stone-100">
            Burn-up, Sprint 14
          </h3>
          <p className="mb-2 text-xs text-stone-500">
            Points in scope against points done, day by day, with the pace that would land on Oct 5.
          </p>
          <LineChart
            label="Sprint 14 burn-up in story points"
            summary={`Scope is ${burn.filter((b) => b.values.scope !== null).at(-1)?.values.scope ?? 0} points with ${
