            Cards by status
          </h3>
          <p className="mb-2 text-xs text-stone-500">Where the work is sitting.</p>
          <BarChart
            label="Cards by status"
            data={statusPoints}
            series={[{ id: "cards", label: "Cards" }]}
            height={220}
            legend={false}
          />
