        <section className={cn(panel, "lg:col-span-2")} aria-labelledby="deck-people">
          <h3 id="deck-people" className="text-sm font-medium text-stone-900 dark:text-stone-100">
            Points by assignee
          </h3>
          <p className="mb-2 text-xs text-stone-500">Stacked by status, in each column&apos;s colour.</p>
          <BarChart
            label="Story points by assignee, stacked by status"
